            r={"Parameters":[{k:p.get(k) for k in ["Name","Type","KeyId","LastModifiedDate","LastModifiedUser","Description","Value","Version","Tier","DataType"]} for p in page]}
            if start+maxr < len(hist): r["NextToken"]=str(start+maxr)
            return r
