            name=req.get("Name"); val=req.get("Value")
            existing=s.params.get(name)
            ver=(existing["Version"]+1) if existing else 1
            user=existing["LastModifiedUser"] if existing else "arn:aws:iam::123456789012:user/testuser"
            p=s.put_raw(name,val,version=ver,desc=req.get("Description",""),modified=1700000000.0+ver*100, keyid=req.get("KeyId",""), ptype=req.get("Type","SecureString"))
