            if req.get("Tags"):
                s.tags[name]=req["Tags"][:]
            return {"Version":ver,"Tier":"Standard"}
        if op=="DeleteParameter":
            name=req.get("Name")
            s.params.pop(name,None)
            return {}
        if op=="ListTagsForResource":
            rid=req.get("ResourceId")
            return {"TagList":s.tags.get(rid,[])}
        if op=="AddTagsToResource":
            rid=req.get("ResourceId")
            # merge
            existing={t["Key"]:t["Value"] for t in s.tags.get(rid,[])}
            for t in req.get("Tags") or []: existing[t["Key"]]=t["Value"]
            s.tags[rid]=[{"Key":k,"Value":v} for k,v in existing.items()]
            return {}
        if op=="RemoveTagsFromResource":
            rid=req.get("ResourceId"); keys=set(req.get("TagKeys") or [])
            s.tags[rid]=[t for t in s.tags.get(rid,[]) if t["Key"] not in keys]
            return {}
        if op=="GetParameter":
            name=req.get("Name")
            if name in s.params:
                p=s.params[name]; return {"Parameter":{k:p[k] for k in ["Name","Type","Value","Version","LastModifiedDate","ARN","DataType"]}}
            return (400,{"__type":"ParameterNotFound","message":"Parameter not found"})
        return {}
