    srv=http.server.ThreadingHTTPServer(('127.0.0.1',port),H)
    threading.Thread(target=srv.serve_forever,daemon=True).start()
    return srv

def run(args, inp=None, extra_env=None, timeout=10):
    e=os.environ.copy()
    e.update({"AWS_ACCESS_KEY_ID":"testid","AWS_SECRET_ACCESS_KEY":"testsecret","AWS_REGION":"us-east-1","AWS_ENDPOINT_URL":"http://127.0.0.1:4567"})
    if extra_env: e.update(extra_env)
