    try:
        p=subprocess.run(["./executable"]+args, input=inp, capture_output=True, text=True, env=e, timeout=timeout)
        print(f"=== {args} inp={inp!r} => {p.returncode}\nOUT:{p.stdout!r}\nERR:{p.stderr!r}\nLOG:{STORE.log}", flush=True)
        return p
