import http.server, threading, subprocess, os, json, base64, copy
class SM:
    def __init__(self):
        self.secrets={} # name -> dict with versions list [(id, string, created, stages)], created etc.
        self.log=[]
    def reset(self): self.__init__()
    def add(self,name,secretstring,versionid="v1",created=1700000000.0,stages=["AWSCURRENT"]):
        s=self.secrets.get(name)
        if s is None:
            s={"Name":name,"ARN":f"arn:aws:secretsmanager:us-east-1:123456789012:secret:{name}","CreatedDate":created,"Versions":[],"LastChangedDate":created,"Tags":[],"Description":"","KmsKeyId":""}
            self.secrets[name]=s
        # clear current stage from others if stages includes AWSCURRENT
        if "AWSCURRENT" in stages:
            for v in s["Versions"]:
                if "AWSCURRENT" in v["VersionStages"]: v["VersionStages"]=["AWSPREVIOUS" if x=="AWSCURRENT" else x for x in v["VersionStages"]]
        s["Versions"].append({"VersionId":versionid,"SecretString":secretstring,"CreatedDate":created,"VersionStages":stages})
        s["LastChangedDate"]=created
        return s
STORE=SM()
class H(http.server.BaseHTTPRequestHandler):
    def do_POST(self):
        length=int(self.headers.get('Content-Length') or 0); body=self.rfile.read(length) if length else b''
        req=json.loads(body or b'{}'); target=self.headers.get('X-Amz-Target',''); op=target.split('.')[-1]
        STORE.log.append((op,req)); print(f"REQ {op} {req}",flush=True)
        status,resp=self.handle_op(op,req)
        payload=json.dumps(resp).encode()
        self.send_response(status); self.send_header('Content-Type','application/x-amz-json-1.1'); self.send_header('Content-Length',str(len(payload))); self.send_header('x-amzn-RequestId','req-1'); self.end_headers(); self.wfile.write(payload)
    def err(self,typ,msg): return (400,{"__type":typ,"message":msg})
    def handle_op(self,op,req):
        s=STORE
        def get_secret(sid):
            # by name or ARN
            if sid in s.secrets: return s.secrets[sid]
            for sec in s.secrets.values():
                if sec["ARN"]==sid: return sec
            return None
        if op=="GetSecretValue":
            sec=get_secret(req.get("SecretId"))
            if not sec: return self.err("ResourceNotFoundException",f"Secrets Manager can't find the specified secret.")
            ver=None
            if req.get("VersionId"):
                ver=next((v for v in sec["Versions"] if v["VersionId"]==req["VersionId"]),None)
            elif req.get("VersionStage"):
                ver=next((v for v in sec["Versions"] if req["VersionStage"] in v["VersionStages"]),None)
            else:
                ver=next((v for v in sec["Versions"] if "AWSCURRENT" in v["VersionStages"]), sec["Versions"][-1] if sec["Versions"] else None)
            if not ver: return self.err("ResourceNotFoundException","version not found")
            return (200,{"ARN":sec["ARN"],"Name":sec["Name"],"VersionId":ver["VersionId"],"SecretString":ver["SecretString"],"VersionStages":ver["VersionStages"],"CreatedDate":ver["CreatedDate"]})
        if op=="ListSecretVersionIds":
            sec=get_secret(req.get("SecretId"))
            if not sec: return self.err("ResourceNotFoundException","not found")
            return (200,{"ARN":sec["ARN"],"Name":sec["Name"],"Versions":[{"VersionId":v["VersionId"],"VersionStages":v["VersionStages"],"CreatedDate":v["CreatedDate"],"LastAccessedDate":v["CreatedDate"],"KmsKeyIds":["default"]} for v in sec["Versions"]]})
        if op=="DescribeSecret":
            sec=get_secret(req.get("SecretId"))
            if not sec: return self.err("ResourceNotFoundException","not found")
            vmap={v["VersionId"]:v["VersionStages"] for v in sec["Versions"]}
            return (200,{"ARN":sec["ARN"],"Name":sec["Name"],"CreatedDate":sec["CreatedDate"],"LastChangedDate":sec["LastChangedDate"],"Tags":sec.get("Tags",[]),"VersionIdsToStages":vmap,"Description":sec.get("Description","")})
        if op=="CreateSecret":
            name=req.get("Name")
            sec=s.add(name,req.get("SecretString",""),versionid="v1",created=1700000100.0)
            if req.get("Tags"): sec["Tags"]=req["Tags"]
            if req.get("Description"): sec["Description"]=req["Description"]
            return (200,{"ARN":sec["ARN"],"Name":name,"VersionId":"v1"})
        if op=="PutSecretValue":
            sec=get_secret(req.get("SecretId"))
            if not sec: return self.err("ResourceNotFoundException","not found")
            vid=f"v{len(sec['Versions'])+1}"
            s.add(sec["Name"], req.get("SecretString",""), versionid=vid, created=1700000100.0+len(sec["Versions"])*100)
            return (200,{"ARN":sec["ARN"],"Name":sec["Name"],"VersionId":vid,"VersionStages":["AWSCURRENT"]})
        if op=="UpdateSecret":
            sec=get_secret(req.get("SecretId"))
            if not sec: return self.err("ResourceNotFoundException","not found")
            vid=f"v{len(sec['Versions'])+1}"
            if "SecretString" in req: s.add(sec["Name"], req["SecretString"],versionid=vid,created=1700000100.0)
            return (200,{"ARN":sec["ARN"],"Name":sec["Name"],"VersionId":vid})
        if op=="DeleteSecret":
            sec=get_secret(req.get("SecretId"))
            if sec: del s.secrets[sec["Name"]]
            return (200,{"ARN":sec["ARN"] if sec else "","Name":req.get("SecretId"),"DeletionDate":1700000000.0})
        if op=="ListSecrets":
