{"command":"cat > utils.go <<'GO'
package main

import (
	"errors"
	"fmt"
	"os"
	"regexp"
	"sort"
	"strings"
	"text/tabwriter"
	"time"
	"unicode"
)

var (
	errSecretNotFound = errors.New("secret not found")
	keyPattern        = regexp.MustCompile(`^[A-Za-z0-9_.\-]+$`)
	servicePattern    = regexp.MustCompile(`^[A-Za-z0-9_.\-]+(/[A-Za-z0-9_.\-]+)*$`)
	// The label form requires at least one slash before the first colon.
	serviceWithLabelPattern = regexp.MustCompile(`^[A-Za-z0-9_.\-]+((/[A-Za-z0-9_.\-]+)+(:[A-Za-z0-9_.\-]+)*)?$`)
	tagKeyPattern           = regexp.MustCompile(`^[A-Za-z0-9 \+\-=._:/@]{1,128}$`)
	tagValuePattern         = regexp.MustCompile(`^[A-Za-z0-9 \+\-=._:/@]{1,256}$`)
	ssmNamePattern          = regexp.MustCompile(`^/([A-Za-z0-9_.\-]+/)*([A-Za-z0-9_.\-]+)$`)
	shellSafePattern        = regexp.MustCompile(`^[a-zA-Z0-9_@%+=:,./-]+$`)
)

const timeFormat = "2006-01-02 15:04:05"

func newTabWriter() *tabwriter.Writer {
	return tabwriter.NewWriter(os.Stdout, 0, 8, 2, '\t', 0)
}

func validateServiceName(service string, allowLabel bool) error {
	if allowLabel {
		if !serviceWithLabelPattern.MatchString(service) {
			return fmt.Errorf("Failed to validate service name '%s'. Only alphanumeric, dashes, forward slashes, full stops and underscores are allowed for service names, and colon followed by a label name. Service names must not start or end with a forward slash or colon", service)
		}
		return nil
	}
	if !servicePattern.MatchString(service) {
		return fmt.Errorf("Failed to validate service name '%s'. Only alphanumeric, dashes, forward slashes, full stops and underscores are allowed for service names. Service names must not start or end with a forward slash", service)
	}
	return nil
}

func validateService(service string, allowLabel bool) error {
	if err := validateServiceName(service, allowLabel); err != nil {
		return fmt.Errorf("Failed to validate service: %w", err)
	}
	return nil
}

func validateKeyName(key string) error {
	if !keyPattern.MatchString(key) {
		return fmt.Errorf("Failed to validate key name '%s'. Only alphanumeric, dashes, full stops and underscores are allowed for key names", key)
	}
	return nil
}

func validateKey(key string) error {
	if err := validateKeyName(key); err != nil {
		return fmt.Errorf("Failed to validate key: %w", err)
	}
	return nil
}

func validateTagKeyName(key string) error {
	if !tagKeyPattern.MatchString(key) {
		return fmt.Errorf("Failed to validate tag key '%s'. Only 128 alphanumeric, space, and characters +-=._:/@ are allowed for tag keys", key)
	}
	return nil
}

func validateTagValueName(value string) error {
	if !tagValuePattern.MatchString(value) {
		return fmt.Errorf("Failed to validate tag value '%s'. Only 256 alphanumeric, space, and characters +-=._:/@ are allowed for tag values", value)
	}
	return nil
}

// rawKey returns the last path-like component in a stored key. Several
// backends use it when converting their internal records into secrets.
func rawKey(key string) string {
	if i := strings.LastIndex(key, "/"); i >= 0 {
		return key[i+1:]
	}
	return key
}

func normalizeEnvName(key string, preserveCase bool) string {
	var b strings.Builder
	for _, r := range key {
		switch {
		case r == '-' || r == '.' || unicode.IsSpace(r):
			b.WriteRune('_')
		default:
			b.WriteRune(r)
		}
	}
	name := b.String()
	if !preserveCase {
		name = strings.ToUpper(name)
	}
	return name
}

func validateShellVariableName(name string) error {
	if name == "" {
		return fmt.Errorf("cmd: %q contains invalid characters for a shell variable name", name)
	}
	for _, r := range name {
		if !(r == '_' || (r >= '0' && r <= '9') || (r >= 'A' && r <= 'Z') || (r >= 'a' && r <= 'z')) {
			return fmt.Errorf("cmd: %q contains invalid characters for a shell variable name", name)
		}
	}
	// At this point name is ASCII, so a byte-wise check is safe.
	if name[0] >= '0' && name[0] <= '9' {
		return fmt.Errorf("cmd: shell variable name %q must start with a letter or underscore", name)
	}
	return nil
}

func shellQuote(s string) string {
	if s == "" {
		return "''"
	}
	if shellSafePattern.MatchString(s) {
		return s
	}
	return "'" + strings.ReplaceAll(s, "'", "'\"'\"'") + "'"
}

var doubleQuoteEscaper = strings.NewReplacer(
	`\`, `\\`,
	"\n", `\n`,
	"\r", `\r`,
	`"`, `\"`,
	"$", `\$`,
	"`", "\\`",
)

func escapeDoubleQuoted(s string) string {
	return `"` + doubleQuoteEscaper.Replace(s) + `"`
}

func sortedKeys[V any](m map[string]V) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func formatTime(t time.Time) string {
	return t.Format(timeFormat)
}

func normalizeKMSAlias(alias string) string {
	return "alias/" + strings.TrimPrefix(alias, "alias/")
}

func strVal(p *string) string {
	if p == nil {
		return ""
	}
	return *p
}

func strPtr(s string) *string { return &s }
GO
gofmt -w utils.go"}

