{"command":"cat > store.go <<'GO'
package main

import (
	"context"
	"errors"
	"fmt"
	"os"
	"strconv"
	"strings"
	"time"

	"github.com/spf13/cobra"
)

type SecretID struct {
	Service string
	Key     string
}

type Secret struct {
	ID           SecretID
	Value        string
	Version      int64
	LastModified time.Time
	User         string
}

type Tag struct {
	Key   string
	Value string
}

type secretStore interface {
	Read(context.Context, SecretID, int64) (Secret, error)
	Write(context.Context, SecretID, string) error
	WriteWithTags(context.Context, SecretID, string, map[string]string) error
	Delete(context.Context, SecretID) error
	List(context.Context, string, bool) ([]Secret, error)
	ListRaw(context.Context, string) (map[string]string, error)
	History(context.Context, SecretID) ([]Secret, error)
	ListServices(context.Context, string, bool) ([]string, error)
	ReadTags(context.Context, SecretID) ([]Tag, error)
	WriteTags(context.Context, SecretID, map[string]string, bool) error
	DeleteTags(context.Context, SecretID, []string) error
}

type nullStore struct{}

func (nullStore) Read(context.Context, SecretID, int64) (Secret, error) {
	return Secret{}, errors.New("Not implemented for Null Store")
}
func (nullStore) Write(context.Context, SecretID, string) error {
	return errors.New("Write is not implemented for Null Store")
}
func (nullStore) WriteWithTags(context.Context, SecretID, string, map[string]string) error {
	return errors.New("WriteWithTags is not implemented for Null Store")
}
func (nullStore) Delete(context.Context, SecretID) error {
