func parseINIFile(path string, isConfig bool, into map[string]map[string]string) {
	data, err := os.ReadFile(path)
	if err != nil {
		return
	}
	current := ""
	for _, rawLine := range strings.Split(string(data), "\n") {
		line := strings.TrimSpace(rawLine)
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
			continue
		}
		if strings.HasPrefix(line, "[") {
			end := strings.Index(line, "]")
			if end < 0 {
				current = ""
				continue
			}
			name := strings.TrimSpace(line[1:end])
			if isConfig {
				name = strings.TrimPrefix(name, "profile ")
			}
			current = name
			if _, ok := into[current]; !ok {
				into[current] = map[string]string{}
			}
			continue
		}
		if current == "" {
			continue
		}
		sep := strings.IndexAny(line, "=:")
		if sep < 0 {
			continue
		}
		key := strings.ToLower(strings.TrimSpace(line[:sep]))
		value := strings.TrimSpace(line[sep+1:])
		into[current][key] = value
	}
}

func awsHomeDir() string {
	if home, err := os.UserHomeDir(); err == nil {
		return home
	}
	return os.Getenv("HOME")
}

func loadAWSConfig(retries int, retryMode string) (*awsConfig, error) {
	home := awsHomeDir()
	credFile := os.Getenv("AWS_SHARED_CREDENTIALS_FILE")
	if credFile == "" && home != "" {
		credFile = filepath.Join(home, ".aws", "credentials")
	}
	configFile := os.Getenv("AWS_CONFIG_FILE")
	if configFile == "" && home != "" {
		configFile = filepath.Join(home, ".aws", "config")
	}

	profiles := map[string]map[string]string{}
	if credFile != "" {
		parseINIFile(credFile, false, profiles)
	}
	if configFile != "" {
		parseINIFile(configFile, true, profiles)
	}

	profileExplicit := false
	profile := "default"
	if v := os.Getenv("AWS_PROFILE"); v != "" {
		profile = v
		profileExplicit = true
	} else if v := os.Getenv("AWS_DEFAULT_PROFILE"); v != "" {
		profile = v
	}
	prof, ok := profiles[profile]
	if profileExplicit && !ok {
		return nil, fmt.Errorf("failed to get shared config profile, %s", profile)
	}
	if !ok {
		profile = "default"
		prof = profiles[profile]
		if prof == nil {
			prof = map[string]string{}
		}
	}

	region := os.Getenv("AWS_REGION")
	if region == "" {
		region = os.Getenv("AWS_DEFAULT_REGION")
	}
	if region == "" {
		region = prof["region"]
	}

	return &awsConfig{
		Region:     region,
		Profile:    profile,
		profile:    prof,
		profiles:   profiles,
		endpoint:   prof["endpoint_url"],
		retries:    retries,
		retryMode:  retryMode,
		httpClient: &http.Client{},
	}, nil
}

func (c *awsConfig) maxAttempts() int {
	if c.retries == 0 {
		return 3
	}
	return c.retries
}

func (c *awsConfig) serviceEndpoint(service string) string {
	envNames := map[string]string{
		"ssm":            "AWS_ENDPOINT_URL_SSM",
		"secretsmanager": "AWS_ENDPOINT_URL_SECRETS_MANAGER",
		"s3":             "AWS_ENDPOINT_URL_S3",
		"sts":            "AWS_ENDPOINT_URL_STS",
		"kms":            "AWS_ENDPOINT_URL_KMS",
	}
	if name := envNames[service]; name != "" {
		if v := os.Getenv(name); v != "" {
			return strings.TrimRight(v, "/")
		}
	}
	if v := os.Getenv("AWS_ENDPOINT_URL"); v != "" {
		return strings.TrimRight(v, "/")
	}
	if c.endpoint != "" {
		return strings.TrimRight(c.endpoint, "/")
	}
	return ""
}

// credentialError carries the SDK-style inner identity failure text.
type credentialError struct {
	text      string
	retryable bool
}

func (e *credentialError) Error() string { return e.text }

const imdsDisabledText = `failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, access disabled to EC2 IMDS via client option, or "AWS_EC2_METADATA_DISABLED" environment variable`

func staticFromProfile(p map[string]string) *awsCredentials {
	id := p["aws_access_key_id"]
	sec := p["aws_secret_access_key"]
	if id == "" || sec == "" {
		return nil
	}
	tok := p["aws_session_token"]
	if tok == "" {
		tok = p["session_token"]
	}
	return &awsCredentials{id, sec, tok}
}

func (c *awsConfig) processCredentials(command string) (*awsCredentials, error) {
	cmd := exec.Command("/bin/sh", "-c", command)
	out, err := cmd.Output()
	if err != nil {
		return nil, err
	}
	var doc struct {
		AccessKeyID     string `json:"AccessKeyId"`
		SecretAccessKey string `json:"SecretAccessKey"`
		SessionToken    string `json:"SessionToken"`
	}
	if err := json.Unmarshal(out, &doc); err != nil {
		return nil, err
	}
	if doc.AccessKeyID == "" || doc.SecretAccessKey == "" {
		return nil, fmt.Errorf("credential process returned no credentials")
	}
	return &awsCredentials{doc.AccessKeyID, doc.SecretAccessKey, doc.SessionToken}, nil
}

func (c *awsConfig) containerCredentials(ctx context.Context) (*awsCredentials, error) {
	full := os.Getenv("AWS_CONTAINER_CREDENTIALS_FULL_URI")
	rel := os.Getenv("AWS_CONTAINER_CREDENTIALS_RELATIVE_URI")
	endpoint := full
	if endpoint == "" && rel != "" {
		endpoint = "http://169.254.170.2" + rel
	}
	if endpoint == "" {
		return nil, nil
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return nil, err
	}
	if tok := os.Getenv("AWS_CONTAINER_AUTHORIZATION_TOKEN"); tok != "" {
		req.Header.Set("Authorization", tok)
	}
	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(resp.Body)
	var doc struct {
		AccessKeyID     string `json:"AccessKeyId"`
		SecretAccessKey string `json:"SecretAccessKey"`
		Token           string `json:"Token"`
	}
	if err := json.Unmarshal(body, &doc); err != nil {
		return nil, err
	}
	if doc.AccessKeyID == "" {
		return nil, nil
	}
	return &awsCredentials{doc.AccessKeyID, doc.SecretAccessKey, doc.Token}, nil
}

func imdsDisabled() bool {
	return strings.EqualFold(os.Getenv("AWS_EC2_METADATA_DISABLED"), "true")
}

func (c *awsConfig) imdsCredentials(ctx context.Context) (*awsCredentials, error) {
	endpoint := os.Getenv("AWS_EC2_METADATA_SERVICE_ENDPOINT")
	if endpoint == "" {
		if strings.EqualFold(os.Getenv("AWS_EC2_METADATA_SERVICE_ENDPOINT_MODE"), "IPv6") {
			endpoint = "http://[fd00:ec2::254]"
		} else {
			endpoint = "http://169.254.169.254"
		}
	}
	endpoint = strings.TrimRight(endpoint, "/")
	credURL := endpoint + "/latest/meta-data/iam/security-credentials/"

	client := &http.Client{Timeout: 2 * time.Second}
	var lastErr error
	var role string
	for attempt := 0; attempt < 3; attempt++ {
		if attempt > 0 {
			time.Sleep(150 * time.Millisecond)
		}
		// Try an IMDSv2 token first, then fall back to a plain request,
		// matching the SDK behaviour when tokens are unavailable.
		token := ""
		if treq, err := http.NewRequestWithContext(ctx, http.MethodPut, endpoint+"/latest/api/token", nil); err == nil {
			treq.Header.Set("x-aws-ec2-metadata-token-ttl-seconds", "21600")
			if tresp, terr := client.Do(treq); terr == nil {
				tb, _ := io.ReadAll(tresp.Body)
				tresp.Body.Close()
				if tresp.StatusCode/100 == 2 {
					token = string(tb)
				}
			}
		}
		req, err := http.NewRequestWithContext(ctx, http.MethodGet, credURL, nil)
		if err != nil {
			return nil, err
		}
		if token != "" {
			req.Header.Set("x-aws-ec2-metadata-token", token)
		}
		resp, err := client.Do(req)
		if err != nil {
			lastErr = err
			continue
		}
		body, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		if resp.StatusCode == http.StatusNotFound {
			return nil, &credentialError{text: "failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, https response error StatusCode: 404, RequestID: , api error UnknownError: UnknownError"}
		}
		if resp.StatusCode/100 != 2 {
			lastErr = fmt.Errorf("unexpected status %d", resp.StatusCode)
			continue
		}
		role = strings.TrimSpace(strings.Split(string(body), "\n")[0])
		lastErr = nil
		break
	}
	if lastErr != nil {
		return nil, &credentialError{
			text:      fmt.Sprintf("failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, exceeded maximum number of attempts, 3, request send failed, %v", lastErr),
			retryable: true,
		}
	}
	if role == "" {
		return nil, &credentialError{text: "failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, https response error StatusCode: 404, RequestID: , api error UnknownError: UnknownError"}
	}
	req, _ := http.NewRequestWithContext(ctx, http.MethodGet, credURL+url.PathEscape(role), nil)
	resp, err := client.Do(req)
	if err != nil {
		return nil, &credentialError{text: fmt.Sprintf("failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, exceeded maximum number of attempts, 3, request send failed, %v", err), retryable: true}
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(resp.Body)
	var doc struct {
		AccessKeyID     string `json:"AccessKeyId"`
		SecretAccessKey string `json:"SecretAccessKey"`
		Token           string `json:"Token"`
	}
	if err := json.Unmarshal(body, &doc); err != nil || doc.AccessKeyID == "" {
		return nil, &credentialError{text: "failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, https response error StatusCode: 404, RequestID: , api error UnknownError: UnknownError"}
	}
	return &awsCredentials{doc.AccessKeyID, doc.SecretAccessKey, doc.Token}, nil
}

func (c *awsConfig) sourceCredentials(ctx context.Context, prof map[string]string) (*awsCredentials, error) {
	if cp := prof["credential_process"]; cp != "" {
		return c.processCredentials(cp)
	}
	if s := staticFromProfile(prof); s != nil {
		return s, nil
	}
	return nil, nil
}

func (c *awsConfig) resolveCredentials(ctx context.Context) (*awsCredentials, error) {
	if c.credsFetched {
		return c.creds, c.credsErr
	}
	c.credsFetched = true

	if id, sec := os.Getenv("AWS_ACCESS_KEY_ID"), os.Getenv("AWS_SECRET_ACCESS_KEY"); id != "" && sec != "" {
		c.creds = &awsCredentials{id, sec, os.Getenv("AWS_SESSION_TOKEN")}
		return c.creds, nil
	}

	prof := c.profile
	if cp := prof["credential_process"]; cp != "" {
		creds, err := c.processCredentials(cp)
		if err == nil && creds != nil {
			c.creds = creds
			return c.creds, nil
		}
		if err != nil {
			c.credsErr = &credentialError{text: fmt.Sprintf("failed to refresh cached credentials, %v", err)}
			return nil, c.credsErr
		}
	}
	if s := staticFromProfile(prof); s != nil {
		c.creds = s
		return c.creds, nil
	}
	if roleARN := prof["role_arn"]; roleARN != "" {
		var source *awsCredentials
		var err error
		if spName := prof["source_profile"]; spName != "" {
			if sp := c.profiles[spName]; sp != nil {
				source, err = c.sourceCredentials(ctx, sp)
			}
		} else if cs := prof["credential_source"]; cs == "Environment" {
			if id, sec := os.Getenv("AWS_ACCESS_KEY_ID"), os.Getenv("AWS_SECRET_ACCESS_KEY"); id != "" && sec != "" {
				source = &awsCredentials{id, sec, os.Getenv("AWS_SESSION_TOKEN")}
			}
		} else if cs == "Ec2InstanceMetadata" && !imdsDisabled() {
			source, err = c.imdsCredentials(ctx)
		}
		if err == nil && source != nil {
			region := c.Region
			cloned := *c
			cloned.creds = source
			cloned.credsFetched = true
			cloned.credsErr = nil
			sts := newSTSClient(&cloned)
			sessionName := prof["role_session_name"]
			if sessionName == "" {
				sessionName = "aws-sdk-go-v2-" + strconv.FormatInt(time.Now().Unix(), 10)
			}
			creds, aerr := sts.assumeRole(ctx, roleARN, sessionName, prof["external_id"])
			_ = region
			if aerr == nil && creds != nil {
				c.creds = creds
				return c.creds, nil
			}
			if aerr != nil {
				c.credsErr = aerr
				return nil, aerr
			}
		}
	}

	// Web identity from the environment.
	roleARN := os.Getenv("AWS_ROLE_ARN")
	tokenFile := os.Getenv("AWS_WEB_IDENTITY_TOKEN_FILE")
	if roleARN == "" {
		roleARN = prof["web_identity_role_arn"]
	}
	if tokenFile == "" {
		tokenFile = prof["web_identity_token_file"]
	}
	if roleARN != "" && tokenFile != "" {
		if tokenBytes, err := os.ReadFile(tokenFile); err == nil {
			cloned := *c
			sts := newSTSClient(&cloned)
			sessionName := os.Getenv("AWS_ROLE_SESSION_NAME")
			if sessionName == "" {
				sessionName = "aws-sdk-go-v2-" + strconv.FormatInt(time.Now().Unix(), 10)
			}
			if creds, aerr := sts.assumeRoleWithWebIdentity(ctx, roleARN, sessionName, strings.TrimSpace(string(tokenBytes))); aerr == nil && creds != nil {
				c.creds = creds
				return c.creds, nil
			} else if aerr != nil {
				c.credsErr = aerr
				return nil, aerr
			}
		}
	}

	if creds, err := c.containerCredentials(ctx); err == nil && creds != nil {
		c.creds = creds
		return c.creds, nil
	}

	if imdsDisabled() {
		c.credsErr = &credentialError{text: imdsDisabledText}
		return nil, c.credsErr
	}
	creds, err := c.imdsCredentials(ctx)
	if err != nil {
		c.credsErr = err
		return nil, err
	}
	c.creds = creds
	return c.creds, nil
}

// ---- SigV4 ----

func sha256Hex(b []byte) string {
	h := sha256.Sum256(b)
	return hex.EncodeToString(h[:])
}

func hmacSHA256(key, data []byte) []byte {
	h := hmac.New(sha256.New, key)
	h.Write(data)
	return h.Sum(nil)
}

func uriEncode(s string, encodeSlash bool) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.' || c == '~' || (c == '/' && !encodeSlash) {
			b.WriteByte(c)
		} else {
			fmt.Fprintf(&b, "%%%02X", c)
		}
	}
	return b.String()
}

func canonicalQuery(q url.Values) string {
	keys := make([]string, 0, len(q))
	for k := range q {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var parts []string
	for _, k := range keys {
		vals := append([]string(nil), q[k]...)
		sort.Strings(vals)
		for _, v := range vals {
			parts = append(parts, uriEncode(k, true)+"="+uriEncode(v, true))
		}
	}
	return strings.Join(parts, "&")
}

func newUUID() string {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		return "00000000-0000-4000-8000-000000000000"
	}
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
}

type signRequest struct {
	Service string
	Region  string
	Time    time.Time
}

// sign applies SigV4 to req in place. It expects host and headers to
// already be populated (except Authorization).
func (c *awsConfig) sign(req *http.Request, creds *awsCredentials, body []byte, service string, signingTime time.Time) {
	payloadHash := sha256Hex(body)
	// Collect canonical headers.
	headers := map[string]string{}
	signedNamesSet := map[string]bool{}
	add := func(name, value string) {
		ln := strings.ToLower(name)
		headers[ln] = strings.Join(strings.Fields(value), " ")
		signedNamesSet[ln] = true
	}
	add("host", req.URL.Host)
	for name, vals := range req.Header {
		ln := strings.ToLower(name)
		if ln == "authorization" || ln == "user-agent" || ln == "x-amz-user-agent" {
			continue
		}
		add(name, strings.Join(vals, ","))
	}
	if req.ContentLength > 0 || (body != nil && len(body) > 0) {
		add("content-length", strconv.FormatInt(req.ContentLength, 10))
	}
	names := make([]string, 0, len(signedNamesSet))
	for n := range signedNamesSet {
		names = append(names, n)
	}
	sort.Strings(names)
	var canonHeaders strings.Builder
	for _, n := range names {
		canonHeaders.WriteString(n + ":" + headers[n] + "\n")
	}
	signedHeaders := strings.Join(names, ";")
	canonicalURI := req.URL.EscapedPath()
	if canonicalURI == "" {
		canonicalURI = "/"
	}
	canonicalRequest := strings.Join([]string{
		req.Method,
		canonicalURI,
		canonicalQuery(req.URL.Query()),
		canonHeaders.String(),
		signedHeaders,
		payloadHash,
	}, "\n")

	amzDate := req.Header.Get("X-Amz-Date")
	dateStamp := signingTime.UTC().Format("20060102")
	scope := fmt.Sprintf("%s/%s/%s/aws4_request", dateStamp, c.Region, service)
	stringToSign := "AWS4-HMAC-SHA256\n" + amzDate + "\n" + scope + "\n" + sha256Hex([]byte(canonicalRequest))

	kDate := hmacSHA256([]byte("AWS4"+creds.SecretAccessKey), []byte(dateStamp))
	kRegion := hmacSHA256(kDate, []byte(c.Region))
	kService := hmacSHA256(kRegion, []byte(service))
	kSigning := hmacSHA256(kService, []byte("aws4_request"))
	signature := hex.EncodeToString(hmacSHA256(kSigning, []byte(stringToSign)))

	req.Header.Set("Authorization", fmt.Sprintf("AWS4-HMAC-SHA256 Credential=%s/%s, SignedHeaders=%s, Signature=%s", creds.AccessKeyID, scope, signedHeaders, signature))
}
