	case "secretsmanager":
		return "https://secretsmanager." + s.cfg.Region + ".amazonaws.com"
	}
	return ""
}

func (s *jsonService) userAgent() string {
	api := ""
	switch s.service {
	case "ssm":
		api = "api/ssm#1.67.3 m/C,E,g"
	case "secretsmanager":
		api = "api/secretsmanager#1.40.1 m/E,g"
