var bareJSONCodes = map[string]map[string]bool{
	"ssm":            bareSet("InternalServerError", "InvalidFilterKey", "InvalidFilterOption", "InvalidFilterValue", "InvalidNextToken", "InvalidKeyId", "InvalidAllowedPattern", "InvalidPolicyAttribute", "InvalidPolicyType", "InvalidResourceType", "ParameterAlreadyExists", "ParameterLimitExceeded", "ParameterPatternMismatchException", "ParameterVersionLimitExceeded", "PoliciesLimitExceeded", "TooManyTagsError", "UnsupportedParameterType", "InvalidResourceId", "TagException"),
	"secretsmanager": bareSet("DecryptionFailure", "EncryptionFailure", "InternalServiceError", "InvalidParameterException", "InvalidRequestException", "LimitExceededException", "MalformedPolicyDocumentException", "PreconditionNotMetException", "ResourceExistsException", "ResourceNotFoundException", "InvalidNextTokenException"),
}

func bareSet(codes ...string) map[string]bool {
	m := map[string]bool{}
	for _, c := range codes {
		m[c] = true
	}
	return m
}

func (s *jsonService) invoke(ctx context.Context, op string, input any, output any) error {
	body, err := json.Marshal(input)
	if err != nil {
		return err
	}
	ep := s.endpoint()
	// Credential failures take precedence over endpoint resolution in
	// the SDK pipeline. execute() resolves credentials first, so only
	// perform the missing-region check once credentials are available.
	if s.cfg.serviceEndpoint(s.service) == "" && s.cfg.endpoint == "" && s.cfg.Region == "" {
		if _, cerr := s.cfg.resolveCredentials(ctx); cerr == nil {
			return s.cfg.endpointMissingRegion(s.display, op, false)
		}
		// Fall through: execute will surface the credential error.
		if ep == "" || strings.Contains(ep, "..") {
			ep = "https://localhost"
		}
	}
	resp, err := s.cfg.execute(ctx, requestSpec{
		Service:   s.service,
		Display:   s.display,
		Operation: op,
		Method:    http.MethodPost,
		URL:       ep + "/",
		Headers: map[string]string{
			"Content-Type": "application/x-amz-json-1.1",
			"X-Amz-Target": s.target + "." + op,
			"User-Agent":   s.userAgent(),
		},
		Body:      body,
		Protocol:  "json",
		BareCodes: bareCodesFor(s.service, op),
	})
	if err != nil {
		return err
	}
	if output != nil && len(resp.Body) > 0 {
		if err := json.Unmarshal(resp.Body, output); err != nil {
			return &apiError{full: operationErrorString(s.display, op, fmt.Sprintf("deserialization failed, %v", err))}
		}
	}
	return nil
}

// SSM's modelled exceptions vary per operation; ParameterNotFound is
// only typed for operations that declare it.
func bareCodesFor(service, op string) map[string]bool {
	base := bareJSONCodes[service]
	if base == nil {
		return nil
	}
	out := map[string]bool{}
	for k, v := range base {
		out[k] = v
	}
	if service == "ssm" {
		switch op {
		case "GetParameterHistory", "DeleteParameter", "GetParameter", "LabelParameterVersion", "UnlabelParameterVersion":
			out["ParameterNotFound"] = true
			out["ParameterVersionNotFound"] = true
		}
	}
	return out
}

