	msg := "Invalid Configuration: Missing Region"
	if isS3 {
		msg = "A region must be set when sending requests to S3."
	}
	return &apiError{full: operationErrorString(display, op, "failed to resolve service endpoint, endpoint rule error, "+msg)}
