	Status int
	Header http.Header
	Body   []byte
}

type requestSpec struct {
	Service       string // signing name
	Display       string // display name in operation errors
	Operation     string
	Method        string
	URL           string
	Headers       map[string]string
	Body          []byte
	Protocol      string // json, xml, query, restxml
	BareCodes     map[string]bool
	Unsigned      bool
	contentSHA256 string // set internally for S3
}

func operationErrorString(display, op, detail string) string {
	return fmt.Sprintf("operation error %s: %s, %s", display, op, detail)
}

func parseJSONAPIError(resp *awsResponse) (code, message string) {
	code = resp.Header.Get("x-amzn-ErrorType")
	var body map[string]interface{}
	if err := json.Unmarshal(resp.Body, &body); err == nil {
		getStr := func(keys ...string) string {
			for _, k := range keys {
				if v, ok := body[k]; ok {
					if s, ok := v.(string); ok {
						return s
					}
				}
			}
			return ""
		}
		if code == "" {
			code = getStr("__type", "code", "Code", "ErrorCode")
		}
		message = getStr("message", "Message", "__Message", "errorMessage")
	}
	if i := strings.Index(code, "#"); i >= 0 {
		code = code[i+1:]
	}
	if i := strings.Index(code, ":"); i >= 0 {
		code = code[:i]
	}
	return code, message
}

type xmlErrorBody struct {
	Code    string `xml:"Code"`
	Message string `xml:"Message"`
}

func parseXMLAPIError(resp *awsResponse) (code, message string) {
	var doc xmlErrorBody
	if err := xml.Unmarshal(resp.Body, &doc); err == nil {
		return doc.Code, doc.Message
	}
	// Query protocol errors nest under Error>.
	var wrapped struct {
		Error xmlErrorBody `xml:"Error"`
	}
	if err := xml.Unmarshal(resp.Body, &wrapped); err == nil {
		return wrapped.Error.Code, wrapped.Error.Message
	}
	return "", ""
}

func requestIDFrom(resp *awsResponse) string {
	for _, h := range []string{"x-amzn-RequestId", "x-amz-RequestId", "x-amzn-RequestID", "RequestId"} {
		if v := resp.Header.Get(h); v != "" {
			return v
		}
	}
	// Query/XML bodies may include a RequestId element.
	var doc struct {
		RequestID string `xml:"RequestId"`
		RequestId string `xml:"RequestID"`
	}
	if err := xml.Unmarshal(resp.Body, &doc); err == nil {
		if doc.RequestID != "" {
			return doc.RequestID
		}
		return doc.RequestId
	}
	return ""
}

func isRetryable(code string, status int) bool {
	if status == 429 || status == 408 || status >= 500 {
		return true
	}
	switch code {
	case "Throttling", "ThrottlingException", "TooManyRequestsException", "RequestLimitExceeded", "SlowDown", "ServiceUnavailable", "InternalError", "InternalServerError", "InternalServiceError", "RequestTimeout", "RequestTimeoutException", "PriorRequestNotComplete", "ConnectionError", "BandwidthLimitExceeded":
		return true
	}
	return false
}

func isThrottle(code string, status int) bool {
	if status == 429 {
		return true
	}
	switch code {
	case "Throttling", "ThrottlingException", "TooManyRequestsException", "RequestLimitExceeded", "SlowDown", "BandwidthLimitExceeded":
		return true
	}
	return false
}

func retryDelay(attempt int, throttle bool, mode string) time.Duration {
	// attempt is the just-failed attempt (1-based).
	base := 200 * time.Millisecond
	if throttle {
		base = 500 * time.Millisecond
	}
	if mode == "adaptive" {
		base = 1000 * time.Millisecond
	}
	maxDelay := base << uint(attempt-1)
	if maxDelay > 20*time.Second || maxDelay <= 0 {
		maxDelay = 20 * time.Second
	}
	return time.Duration(rand.Int63n(int64(maxDelay) + 1))
}

// execute performs a signed AWS HTTP request with SDK-like retry and
// error formatting. Credential and endpoint resolution errors are
// returned in the same operation-error envelope.
func (c *awsConfig) execute(ctx context.Context, spec requestSpec) (*awsResponse, error) {
	maxAttempts := c.maxAttempts()
	effectiveAttempts := maxAttempts
	if effectiveAttempts < 1 {
		// The SDK keeps retrying for negative values; cap to a single
		// attempt here only as a safety valve for our loop bound, while
		// keeping the configured number in headers/messages.
		effectiveAttempts = 1000000
	}

	var lastErr error
	for attempt := 1; attempt <= effectiveAttempts; attempt++ {
		var creds *awsCredentials
		if !spec.Unsigned {
			var err error
			creds, err = c.resolveCredentials(ctx)
			if err != nil {
				if ce, ok := err.(*credentialError); ok {
					detail := "get identity: get credentials: " + ce.text
					opErr := operationErrorString(spec.Display, spec.Operation, detail)
					if !ce.retryable {
						return nil, &apiError{full: opErr}
					}
					lastErr = &apiError{full: operationErrorString(spec.Display, spec.Operation, fmt.Sprintf("exceeded maximum number of attempts, %d, %s", maxAttempts, detail))}
				} else {
					lastErr = &apiError{full: operationErrorString(spec.Display, spec.Operation, "get identity: get credentials: "+err.Error())}
				}
				if attempt < effectiveAttempts {
					time.Sleep(retryDelay(attempt, false, c.retryMode))
					// Do not cache a retryable IMDS failure across attempts.
					if ce, ok := err.(*credentialError); ok && ce.retryable {
						c.credsFetched = false
						c.credsErr = nil
					}
					continue
				}
				return nil, lastErr
			}
		}

		req, err := http.NewRequestWithContext(ctx, spec.Method, spec.URL, bytes.NewReader(spec.Body))
		if err != nil {
			return nil, &apiError{full: operationErrorString(spec.Display, spec.Operation, "request send failed, "+err.Error())}
		}
		now := time.Now().UTC()
		req.Header.Set("X-Amz-Date", now.Format("20060102T150405Z"))
		req.Header.Set("Amz-Sdk-Invocation-Id", newUUID())
		req.Header.Set("Amz-Sdk-Request", fmt.Sprintf("attempt=%d; max=%d", attempt, maxAttempts))
		for k, v := range spec.Headers {
			req.Header.Set(k, v)
		}
		if creds != nil && creds.SessionToken != "" {
			req.Header.Set("X-Amz-Security-Token", creds.SessionToken)
		}
		if spec.contentSHA256 != "" {
			req.Header.Set("X-Amz-Content-Sha256", spec.contentSHA256)
		}
		if !spec.Unsigned {
			c.sign(req, creds, spec.Body, spec.Service, now)
		}

		httpResp, err := c.httpClient.Do(req)
		if err != nil {
			detail := fmt.Sprintf("https response error StatusCode: 0, RequestID: , request send failed, %v", err)
			retryable := true
			if attempt < effectiveAttempts && retryable {
				// Network response may be closed by Do on error.
				time.Sleep(retryDelay(attempt, false, c.retryMode))
				lastErr = &apiError{full: operationErrorString(spec.Display, spec.Operation, detail)}
				continue
			}
			if attempt > 1 || effectiveAttempts == 1 || maxAttempts == 1 {
				detail = fmt.Sprintf("exceeded maximum number of attempts, %d, %s", maxAttempts, detail)
			} else if attempt >= effectiveAttempts {
				detail = fmt.Sprintf("exceeded maximum number of attempts, %d, %s", maxAttempts, detail)
			}
			return nil, &apiError{full: operationErrorString(spec.Display, spec.Operation, detail)}
		}
		body, _ := io.ReadAll(httpResp.Body)
		httpResp.Body.Close()
		resp := &awsResponse{Status: httpResp.StatusCode, Header: httpResp.Header, Body: body}
		if resp.Status/100 == 2 {
			return resp, nil
		}

		var code, message string
		switch spec.Protocol {
		case "json":
			code, message = parseJSONAPIError(resp)
		default:
			code, message = parseXMLAPIError(resp)
		}
		if code == "" {
			code = "UnknownError"
		}
		if message == "" {
			message = "UnknownError"
		}
		rid := requestIDFrom(resp)
		prefix := "api error "
		if spec.BareCodes != nil && spec.BareCodes[code] {
			prefix = ""
		}
		detail := fmt.Sprintf("https response error StatusCode: %d, RequestID: %s, %s%s: %s", resp.Status, rid, prefix, code, message)
		apiErr := &apiError{Code: code, Message: message, RequestID: rid, Status: resp.Status, full: operationErrorString(spec.Display, spec.Operation, detail)}

		if isRetryable(code, resp.Status) {
			if attempt < effectiveAttempts {
				delay := retryDelay(attempt, isThrottle(code, resp.Status), c.retryMode)
				if ra := resp.Header.Get("Retry-After"); ra != "" {
					if secs, perr := strconv.Atoi(strings.TrimSpace(ra)); perr == nil {
						delay = time.Duration(secs) * time.Second
					}
				}
				time.Sleep(delay)
				continue
			}
			apiErr.full = operationErrorString(spec.Display, spec.Operation, fmt.Sprintf("exceeded maximum number of attempts, %d, %s", maxAttempts, detail))
		}
		return nil, apiErr
	}
	if lastErr != nil {
		return nil, lastErr
	}
	return nil, &apiError{full: operationErrorString(spec.Display, spec.Operation, "unknown error")}
}

func (c *awsConfig) endpointMissingRegion(display, op string, isS3 bool) error {
	msg := "Invalid Configuration: Missing Region"
	if isS3 {
		msg = "A region must be set when sending requests to S3."
	}
	return &apiError{full: operationErrorString(display, op, "failed to resolve service endpoint, endpoint rule error, "+msg)}
}

