func (s *s3Client) objectURL(bucket, key string, query url.Values) string {
	ep := s.cfg.serviceEndpoint("s3")
	custom := ep != ""
	if !custom {
		ep = "https://s3." + s.cfg.Region + ".amazonaws.com"
	}
	u, err := url.Parse(ep)
	if err != nil {
		return ep
	}
	host := u.Hostname()
	pathStyle := false
	if custom && net.ParseIP(host) != nil {
		pathStyle = true
	}
	if !validDNSBucket(bucket) {
		pathStyle = true
	}
	encodedKey := ""
	if key != "" {
		parts := strings.Split(key, "/")
		for i, p := range parts {
			parts[i] = uriEncode(p, true)
		}
		encodedKey = strings.Join(parts, "/")
	}
	basePath := strings.TrimRight(u.EscapedPath(), "/")
	if pathStyle {
		u.Path = ""
		p := basePath + "/" + uriEncode(bucket, true)
		if encodedKey != "" {
			p += "/" + encodedKey
		}
		u.RawPath = p
		// url.URL.String uses EscapedPath via RawPath when valid.
		// Setting Path to the decoded form helps non-ASCII keys.
		decoded := basePath + "/" + bucket
		if key != "" {
			decoded += "/" + key
		}
		u.Path = decoded
		if u.EscapedPath() != p {
			u.RawPath = p
		}
	} else {
		if u.Port() != "" {
			u.Host = bucket + "." + host + ":" + u.Port()
		} else {
			u.Host = bucket + "." + host
		}
		p := basePath
		if encodedKey != "" {
			p += "/" + encodedKey
		}
		if p == "" {
			p = "/"
		}
		decoded := basePath
		if key != "" {
			decoded += "/" + key
		}
		if decoded == "" {
			decoded = "/"
		}
		u.Path = decoded
		if u.EscapedPath() != p {
			u.RawPath = p
		}
	}
	if query != nil {
		u.RawQuery = canonicalQuery(query)
	}
	return u.String()
}

func validDNSBucket(bucket string) bool {
	if len(bucket) < 3 || len(bucket) > 63 {
		return false
	}
	if net.ParseIP(bucket) != nil {
		return false
	}
	for i, r := range bucket {
		if !(r >= 'a' && r <= 'z' || r >= '0' && r <= '9' || r == '-' || r == '.') {
			return false
		}
		if (i == 0 || i == len(bucket)-1) && !(r >= 'a' && r <= 'z' || r >= '0' && r <= '9') {
			return false
		}
	}
	if strings.Contains(bucket, "..") {
		return false
	}
	return true
}

func crc32Base64(b []byte) string {
	sum := crc32.ChecksumIEEE(b)
	var buf [4]byte
	buf[0] = byte(sum >> 24)
	buf[1] = byte(sum >> 16)
	buf[2] = byte(sum >> 8)
	buf[3] = byte(sum)
	return base64.StdEncoding.EncodeToString(buf[:])
}

