func (s *s3Client) do(ctx context.Context, op, method, bucket, key string, query url.Values, body []byte, headers map[string]string) (*awsResponse, error) {
	// Credential failures precede endpoint resolution in the SDK.
	if s.cfg.serviceEndpoint("s3") == "" && s.cfg.endpoint == "" && s.cfg.Region == "" {
		if _, cerr := s.cfg.resolveCredentials(ctx); cerr == nil {
			return nil, s.cfg.endpointMissingRegion("S3", op, true)
		}
	}
	if query == nil {
		query = url.Values{}
	}
	if _, ok := query["x-id"]; !ok {
		query.Set("x-id", op)
	}
	merged := map[string]string{
		"Accept-Encoding": "identity",
		"User-Agent":      fmt.Sprintf("aws-sdk-go-v2/1.40.0 ua/2.1 os/linux lang/go#1.23.0 md/GOOS#linux md/GOARCH#%s api/s3#1.91.1 m/b,g", rt.GOARCH),
	}
	for k, v := range headers {
		merged[k] = v
	}
	spec := requestSpec{
		Service:   "s3",
		Display:   "S3",
		Operation: op,
		Method:    method,
		URL:       s.objectURL(bucket, key, query),
		Headers:   merged,
		Body:      body,
		Protocol:  "xml",
		BareCodes: s3BareCodes,
