type ssmParameterFilter struct {
	Key    string   `json:"Key"`
	Option string   `json:"Option,omitempty"`
	Values []string `json:"Values,omitempty"`
}

type ssmParameterMetadata struct {
	Name              *string  `json:"Name"`
	LastModifiedDate  *awsTime `json:"LastModifiedDate"`
	LastModifiedUser  *string  `json:"LastModifiedUser"`
	Description       *string  `json:"Description"`
	Version           int64    `json:"Version"`
}

type ssmParameter struct {
	Name             *string  `json:"Name"`
	Value            *string  `json:"Value"`
	Version          int64    `json:"Version"`
	LastModifiedDate *awsTime `json:"LastModifiedDate"`
}

type ssmHistoryParameter struct {
	Name             *string  `json:"Name"`
	Value            *string  `json:"Value"`
	LastModifiedDate *awsTime `json:"LastModifiedDate"`
	LastModifiedUser *string  `json:"LastModifiedUser"`
	Description      *string  `json:"Description"`
	Version          int64    `json:"Version"`
}

func parseSSMName(name string) (SecretID, bool) {
	m := ssmNamePattern.FindStringSubmatch(name)
	if m == nil {
		return SecretID{}, false
	}
	key := m[2]
	rest := strings.TrimSuffix(strings.TrimPrefix(name, "/"), key)
	service := strings.TrimSuffix(rest, "/")
	return SecretID{Service: service, Key: key}, true
}

func ssmFQName(id SecretID) string {
	service := strings.ToLower(id.Service)
	if service == "" {
		return "/" + id.Key
	}
	return "/" + service + "/" + id.Key
}

func parameterMetaToSecretMeta(meta ssmParameterMetadata) (Secret, bool) {
	id, ok := parseSSMName(strVal(meta.Name))
	if !ok {
		return Secret{}, false
	}
	version, _ := strconv.ParseInt(strVal(meta.Description), 10, 64)
	return Secret{
		ID:           id,
		Version:      version,
		LastModified: meta.LastModifiedDate.Time,
		User:         strVal(meta.LastModifiedUser),
	}, true
}

