func (s *ssmStore) WriteTags(ctx context.Context, id SecretID, tags map[string]string, deleteOther bool) error {
	if deleteOther {
		existing, err := s.ReadTags(ctx, id)
		if err != nil {
			return err
		}
		cfg, err := s.getStoreConfig(ctx)
		if err != nil {
			return err
		}
		var mustRewrite []string
		for _, required := range cfg.RequiredTags {
			present := false
			for _, t := range existing {
				if t.Key == required {
					present = true
					break
				}
			}
			if present {
				if _, ok := tags[required]; !ok {
					mustRewrite = append(mustRewrite, required)
				}
			}
		}
		if len(mustRewrite) > 0 {
			return fmt.Errorf("required tags %v are already present, so they must be rewritten", mustRewrite)
		}
		var toDelete []string
		for _, t := range existing {
			if _, ok := tags[t.Key]; !ok {
				toDelete = append(toDelete, t.Key)
			}
		}
		if len(toDelete) > 0 {
			if err := s.DeleteTags(ctx, id, toDelete); err != nil {
				return err
			}
		}
	}
	return s.addTags(ctx, id, tags)
}

func (s *ssmStore) DeleteTags(ctx context.Context, id SecretID, keys []string) error {
	cfg, err := s.getStoreConfig(ctx)
	if err != nil {
		return err
	}
	var forbidden []string
	for _, required := range cfg.RequiredTags {
		if containsString(keys, required) {
			forbidden = append(forbidden, required)
		}
	}
	if len(forbidden) > 0 {
		return fmt.Errorf("required tags %v may not be deleted", forbidden)
	}
	input := map[string]any{"ResourceId": ssmFQName(id), "ResourceType": "Parameter", "TagKeys": keys}
	return s.client.invoke(ctx, "RemoveTagsFromResource", input, &struct{}{})
}
