)

type ssmStore struct {
	client   *jsonService
	kmsKeyID string
}

type ssmParameterFilter struct {
	Key    string   `json:"Key"`
	Option string   `json:"Option,omitempty"`
	Values []string `json:"Values,omitempty"`
}

type ssmParameterMetadata struct {
	Name              *string  `json:"Name"`
	LastModifiedDate  *awsTime `json:"LastModifiedDate"`
	LastModifiedUser  *string  `json:"LastModifiedUser"`
	Description       *string  `json:"Description"`
	Version           int64    `json:"Version"`
}

type ssmParameter struct {
	Name             *string  `json:"Name"`
	Value            *string  `json:"Value"`
	Version          int64    `json:"Version"`
	LastModifiedDate *awsTime `json:"LastModifiedDate"`
}

type ssmHistoryParameter struct {
	Name             *string  `json:"Name"`
	Value            *string  `json:"Value"`
	LastModifiedDate *awsTime `json:"LastModifiedDate"`
	LastModifiedUser *string  `json:"LastModifiedUser"`
	Description      *string  `json:"Description"`
	Version          int64    `json:"Version"`
}

func parseSSMName(name string) (SecretID, bool) {
	m := ssmNamePattern.FindStringSubmatch(name)
	if m == nil {
		return SecretID{}, false
	}
	key := m[2]
	rest := strings.TrimSuffix(strings.TrimPrefix(name, "/"), key)
	service := strings.TrimSuffix(rest, "/")
	return SecretID{Service: service, Key: key}, true
}

func ssmFQName(id SecretID) string {
	service := strings.ToLower(id.Service)
	if service == "" {
		return "/" + id.Key
	}
	return "/" + service + "/" + id.Key
}

func parameterMetaToSecretMeta(meta ssmParameterMetadata) (Secret, bool) {
	id, ok := parseSSMName(strVal(meta.Name))
	if !ok {
		return Secret{}, false
	}
	version, _ := strconv.ParseInt(strVal(meta.Description), 10, 64)
	return Secret{
		ID:           id,
		Version:      version,
		LastModified: meta.LastModifiedDate.Time,
		User:         strVal(meta.LastModifiedUser),
	}, true
}

func (s *ssmStore) describeParameters(ctx context.Context, filters []ssmParameterFilter, maxResults *int) ([]ssmParameterMetadata, error) {
	var out []ssmParameterMetadata
	var token *string
	for {
		input := map[string]any{"ParameterFilters": filters}
		if maxResults != nil {
			input["MaxResults"] = *maxResults
		}
		if token != nil {
			input["NextToken"] = *token
		}
		var resp struct {
			Parameters []ssmParameterMetadata `json:"Parameters"`
			NextToken  *string                `json:"NextToken"`
		}
		if err := s.client.invoke(ctx, "DescribeParameters", input, &resp); err != nil {
			return nil, err
		}
		out = append(out, resp.Parameters...)
		if resp.NextToken == nil || *resp.NextToken == "" {
			break
		}
		token = resp.NextToken
	}
	return out, nil
}

func (s *ssmStore) getParameters(ctx context.Context, names []string) ([]ssmParameter, error) {
	var resp struct {
		Parameters []ssmParameter `json:"Parameters"`
	}
	input := map[string]any{"Names": names, "WithDecryption": true}
	if err := s.client.invoke(ctx, "GetParameters", input, &resp); err != nil {
		return nil, err
	}
	return resp.Parameters, nil
}

func (s *ssmStore) parameterHistory(ctx context.Context, id SecretID, decrypt bool) ([]ssmHistoryParameter, error) {
	var out []ssmHistoryParameter
	var token *string
	for {
		input := map[string]any{"Name": ssmFQName(id), "WithDecryption": decrypt}
		if token != nil {
			input["NextToken"] = *token
		}
		var resp struct {
			Parameters []ssmHistoryParameter `json:"Parameters"`
			NextToken  *string               `json:"NextToken"`
		}
		if err := s.client.invoke(ctx, "GetParameterHistory", input, &resp); err != nil {
			return nil, err
		}
		out = append(out, resp.Parameters...)
		if resp.NextToken == nil || *resp.NextToken == "" {
			break
		}
		token = resp.NextToken
	}
	return out, nil
}

func historyParamToSecret(id SecretID, p ssmHistoryParameter) Secret {
	version, _ := strconv.ParseInt(strVal(p.Description), 10, 64)
	return Secret{
		ID:           id,
		Value:        strVal(p.Value),
		Version:      version,
		LastModified: p.LastModifiedDate.Time,
		User:         strVal(p.LastModifiedUser),
	}
}

func (s *ssmStore) Read(ctx context.Context, id SecretID, version int64) (Secret, error) {
	if version != -1 {
		hist, err := s.parameterHistory(ctx, id, true)
		if err != nil {
			return Secret{}, err
		}
		for _, p := range hist {
			sec := historyParamToSecret(id, p)
			if sec.Version == version {
				return sec, nil
			}
		}
		return Secret{}, errSecretNotFound
	}

	params, err := s.getParameters(ctx, []string{ssmFQName(id)})
	if err != nil {
		return Secret{}, err
	}
	if len(params) == 0 {
		return Secret{}, errSecretNotFound
	}
	secret := Secret{ID: id, Value: strVal(params[0].Value)}
	listed, err := s.List(ctx, id.Service, false)
	if err != nil {
		return Secret{}, err
	}
	for _, candidate := range listed {
		if candidate.ID == id {
			secret.Version = candidate.Version
			secret.LastModified = candidate.LastModified
			secret.User = candidate.User
			break
		}
	}
	return secret, nil
}

func (s *ssmStore) List(ctx context.Context, service string, expand bool) ([]Secret, error) {
	filters := []ssmParameterFilter{{Key: "Path", Option: "OneLevel", Values: []string{"/" + strings.ToLower(service)}}}
	metas, err := s.describeParameters(ctx, filters, nil)
	if err != nil {
		return nil, err
	}
	byID := map[SecretID]Secret{}
	for _, meta := range metas {
		if sec, ok := parameterMetaToSecretMeta(meta); ok {
			byID[sec.ID] = sec
		}
	}
	if expand && len(byID) > 0 {
		names := make([]string, 0, len(byID))
		for id := range byID {
			names = append(names, ssmFQName(id))
		}
		for i := 0; i < len(names); i += 10 {
			end := i + 10
			if end > len(names) {
				end = len(names)
			}
			params, err := s.getParameters(ctx, names[i:end])
			if err != nil {
				return nil, err
			}
			for _, p := range params {
				id, ok := parseSSMName(strVal(p.Name))
				if !ok {
					continue
				}
				if sec, ok := byID[id]; ok {
					sec.Value = strVal(p.Value)
					byID[id] = sec
				}
			}
		}
	}
	out := make([]Secret, 0, len(byID))
	for _, sec := range byID {
		out = append(out, sec)
	}
	return out, nil
}

func (s *ssmStore) ListRaw(ctx context.Context, service string) (map[string]string, error) {
	out := map[string]string{}
	var token *string
	for {
		input := map[string]any{"Path": "/" + strings.ToLower(service) + "/", "WithDecryption": true}
		if token != nil {
