func (s *ssmStore) ListServices(ctx context.Context, prefix string, includeSecrets bool) ([]string, error) {
	maxResults := 50
	filters := []ssmParameterFilter{{Key: "Name", Option: "BeginsWith", Values: []string{"/" + strings.ToLower(prefix)}}}
	metas, err := s.describeParameters(ctx, filters, &maxResults)
	if err != nil {
		return nil, err
	}
	set := map[string]bool{}
	for _, meta := range metas {
		sec, ok := parameterMetaToSecretMeta(meta)
		if !ok {
			continue
		}
		if includeSecrets {
			set[ssmFQName(sec.ID)] = true
		} else {
			set[sec.ID.Service] = true
		}
	}
	out := make([]string, 0, len(set))
	for name := range set {
		out = append(out, name)
	}
	return out, nil
}

type storeConfig struct {
	Version      string   `json:"version"`
	RequiredTags []string `json:"requiredTags"`
}

func (s *ssmStore) getStoreConfig(ctx context.Context) (storeConfig, error) {
	var cfg storeConfig
	secret, err := s.Read(ctx, SecretID{Service: "_chamber", Key: "store-config"}, -1)
	if err != nil {
		if errors.Is(err, errSecretNotFound) {
			return cfg, nil
		}
		return cfg, err
	}
	if err := json.Unmarshal([]byte(secret.Value), &cfg); err != nil {
		return cfg, fmt.Errorf("failed to unmarshal store config: %w", err)
	}
	return cfg, nil
}

func (s *ssmStore) write(ctx context.Context, id SecretID, value string, tags map[string]string) error {
	existing, err := s.Read(ctx, id, -1)
	version := int64(1)
	isNew := false
	if err != nil {
		if !errors.Is(err, errSecretNotFound) {
			return err
		}
		isNew = true
	} else {
		version = existing.Version + 1
	}

	if isNew {
		cfg, err := s.getStoreConfig(ctx)
		if err != nil {
			return err
		}
		var missing []string
		for _, required := range cfg.RequiredTags {
			if _, ok := tags[required]; !ok {
				missing = append(missing, required)
			}
		}
		if len(missing) > 0 {
			return fmt.Errorf("required tags %v are missing", missing)
		}
	} else if len(tags) > 0 {
		return errors.New("tags on write only supported for new secrets")
	}

	input := map[string]any{
		"Description": strconv.FormatInt(version, 10),
		"KeyId":       s.kmsKeyID,
		"Name":        ssmFQName(id),
		"Overwrite":   true,
		"Type":        "SecureString",
		"Value":       value,
	}
	var out struct {
		Version int64 `json:"Version"`
	}
	if err := s.client.invoke(ctx, "PutParameter", input, &out); err != nil {
		return err
	}
	if len(tags) > 0 {
		if err := s.addTags(ctx, id, tags); err != nil {
			return fmt.Errorf("failed to write tags on successfully created secret: %w", err)
		}
	}
	return nil
}

