package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
	"time"
)

type secretsManagerStore struct {
	client *jsonService
	sts    *stsClient
}

type secretMetadata struct {
	Created   time.Time `json:"created"`
	CreatedBy string    `json:"created_by"`
	Version   int       `json:"version"`
}

type smBundle struct {
	values   map[string]string
	metadata map[string]secretMetadata
}

func stringifySMValue(v interface{}) string {
	switch value := v.(type) {
	case string:
		return value
	case float64:
		return strconv.FormatFloat(value, 'f', -1, 64)
	case bool:
		return strconv.FormatBool(value)
	default:
		return ""
	}
}

func parseSMBundle(secretString string) (smBundle, error) {
	bundle := smBundle{values: map[string]string{}, metadata: map[string]secretMetadata{}}
	if secretString == "" {
		return bundle, errSecretNotFound
	}
	var raw map[string]interface{}
	if err := json.Unmarshal([]byte(secretString), &raw); err != nil {
		return bundle, err
	}
	if metaRaw, ok := raw["_chamber_metadata"]; ok {
		metaString, _ := metaRaw.(string)
		if err := json.Unmarshal([]byte(metaString), &bundle.metadata); err != nil {
			return bundle, err
		}
	}
	for k, v := range raw {
		bundle.values[k] = stringifySMValue(v)
	}
	return bundle, nil
}

type smGetSecretValueOutput struct {
	SecretString *string `json:"SecretString"`
	Name         string  `json:"Name"`
	VersionID    string  `json:"VersionId"`
}

func (s *secretsManagerStore) readVersion(ctx context.Context, service, versionID string) (smBundle, error) {
	input := map[string]any{"SecretId": strings.ToLower(service)}
	if versionID != "" {
		input["VersionId"] = versionID
	}
	var resp smGetSecretValueOutput
	if err := s.client.invoke(ctx, "GetSecretValue", input, &resp); err != nil {
		return smBundle{}, err
	}
	// Match the reference behaviour of dereferencing the returned
	// string directly.
	return parseSMBundle(*resp.SecretString)
}

func (s *secretsManagerStore) readLatest(ctx context.Context, service string) (smBundle, error) {
	return s.readVersion(ctx, service, "")
}

func bundleSecret(bundle smBundle, id SecretID, rawK string) (Secret, bool) {
	value, ok := bundle.values[rawK]
	if !ok {
		return Secret{}, false
	}
	sec := Secret{ID: SecretID{Service: id.Service, Key: rawKey(rawK)}, Value: value}
	if meta, ok := bundle.metadata[rawK]; ok {
		sec.Version = int64(meta.Version)
		sec.LastModified = meta.Created
		sec.User = meta.CreatedBy
	}
	return sec, true
}

func (s *secretsManagerStore) listVersionIDs(ctx context.Context, service string) ([]string, error) {
	var ids []string
	var token *string
	for {
		input := map[string]any{"SecretId": strings.ToLower(service), "IncludeDeprecated": false}
		if token != nil {
			input["NextToken"] = *token
		}
		var resp struct {
			Versions []struct {
				VersionID string `json:"VersionId"`
			} `json:"Versions"`
			NextToken *string `json:"NextToken"`
		}
		if err := s.client.invoke(ctx, "ListSecretVersionIds", input, &resp); err != nil {
			return nil, err
		}
		for _, v := range resp.Versions {
			ids = append(ids, v.VersionID)
		}
		if resp.NextToken == nil || *resp.NextToken == "" {
			break
		}
		token = resp.NextToken
	}
	return ids, nil
}

func (s *secretsManagerStore) Read(ctx context.Context, id SecretID, version int64) (Secret, error) {
	if version != -1 {
		ids, err := s.listVersionIDs(ctx, id.Service)
		if err != nil {
			return Secret{}, err
		}
		for _, vid := range ids {
			bundle, err := s.readVersion(ctx, id.Service, vid)
			if err != nil {
				return Secret{}, err
			}
			if sec, ok := bundleSecret(bundle, id, id.Key); ok {
				if meta, hasMeta := bundle.metadata[id.Key]; hasMeta && int64(meta.Version) == version {
					return sec, nil
				}
			}
		}
		return Secret{}, errSecretNotFound
	}
	bundle, err := s.readLatest(ctx, id.Service)
	if err != nil {
		return Secret{}, err
	}
	if sec, ok := bundleSecret(bundle, id, id.Key); ok {
		sec.ID = id
		return sec, nil
	}
	return Secret{}, errSecretNotFound
}

func (s *secretsManagerStore) List(ctx context.Context, service string, expand bool) ([]Secret, error) {
	bundle, err := s.readLatest(ctx, service)
	if err != nil {
		return nil, err
	}
	out := []Secret{}
	for rawK := range bundle.values {
		if rawK == "_chamber_metadata" {
			continue
		}
		if sec, ok := bundleSecret(bundle, SecretID{Service: service}, rawK); ok {
			out = append(out, sec)
		}
	}
