func (s *s3Store) readHistory(ctx context.Context, id SecretID) (s3SecretHistory, error) {
	resp, err := s.client.getObject(ctx, s.bucket, s.historyKey(id.Service, id.Key))
	if err != nil {
		if isNoSuchKey(err) {
			return s3SecretHistory{}, errSecretNotFound
		}
		return s3SecretHistory{}, err
	}
	var hist s3SecretHistory
	if err := json.Unmarshal(resp.Body, &hist); err != nil {
		return s3SecretHistory{}, err
	}
	return hist, nil
}

func historyToSecrets(id SecretID, hist s3SecretHistory) []Secret {
	out := make([]Secret, 0, len(hist.Values))
	for _, v := range hist.Values {
		out = append(out, Secret{ID: id, Value: v.Value, Version: int64(v.Version), LastModified: v.Created, User: v.CreatedBy})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Version < out[j].Version })
	return out
}

func (s *s3Store) Read(ctx context.Context, id SecretID, version int64) (Secret, error) {
	hist, err := s.readHistory(ctx, id)
	if err != nil {
		return Secret{}, err
	}
	if version != -1 {
		v, ok := hist.Values[int(version)]
		if !ok {
			return Secret{}, errSecretNotFound
		}
		return Secret{ID: id, Value: v.Value, Version: int64(v.Version), LastModified: v.Created, User: v.CreatedBy}, nil
	}
	if len(hist.Values) == 0 {
		return Secret{}, errSecretNotFound
	}
	maxKey := 0
	first := true
	for k := range hist.Values {
		if first || k > maxKey {
			maxKey = k
			first = false
		}
	}
	v := hist.Values[maxKey]
	return Secret{ID: id, Value: v.Value, Version: int64(v.Version), LastModified: v.Created, User: v.CreatedBy}, nil
}

