package main

import (
	"bytes"
	"encoding/csv"
	"encoding/json"
	"fmt"
	"strings"

	"gopkg.in/yaml.v3"
)

func exportParameters(params map[string]string, format string) (string, error) {
	switch strings.ToLower(format) {
	case "json":
		b, err := json.Marshal(params)
		if err != nil {
			return "", err
		}
		return string(b) + "\n", nil
	case "yaml":
		b, err := yaml.Marshal(params)
		if err != nil {
			return "", err
		}
		return string(b), nil
	case "java-properties", "properties":
		var buf strings.Builder
		for _, k := range sortedKeys(params) {
			fmt.Fprintf(&buf, "%s = %s\n", escapePropertyKey(k), escapePropertyValue(params[k]))
		}
		return buf.String(), nil
	case "csv", "tsv":
		var buf bytes.Buffer
		w := csv.NewWriter(&buf)
		if strings.ToLower(format) == "tsv" {
			w.Comma = '\t'
		}
		for _, k := range sortedKeys(params) {
			if err := w.Write([]string{k, params[k]}); err != nil {
				return "", err
			}
		}
		w.Flush()
		if err := w.Error(); err != nil {
			return "", err
		}
		return buf.String(), nil
