{"command":"cat > environ.go <<'GO'
package main

import (
	"context"
	"fmt"
	"log/slog"
	"os"
	"os/exec"
	"strings"
	"syscall"
)

type environ struct {
	vars         []string
	pristine     bool
	strict       bool
	strictValue  string
}

func newEnviron(pristine, strict bool, strictValue string) *environ {
	e := &environ{pristine: pristine, strict: strict, strictValue: strictValue}
	if pristine {
		slog.Debug("chamber: pristine mode engaged")
		e.vars = []string{}
	} else {
		e.vars = append([]string(nil), os.Environ()...)
	}
	if strict {
		slog.Debug("chamber: strict mode engaged")
	}
	return e
}

func splitEnvVar(s string) (string, string) {
	if i := strings.Index(s, "="); i >= 0 {
		return s[:i], s[i+1:]
	}
	return s, ""
}

func (e *environ) get(key string) (string, bool) {
	for _, kv := range e.vars {
		k, v := splitEnvVar(kv)
		if k == key {
			return v, true
		}
	}
	return "", false
}

func (e *environ) has(key string) bool {
	_, ok := e.get(key)
	return ok
}

// set replaces a variable by deleting its old entry (swapping the
// last entry into its place) and appending the new entry.
func (e *environ) set(key, value string) {
	for i, kv := range e.vars {
		if k, _ := splitEnvVar(kv); k == key {
			e.vars[i] = e.vars[len(e.vars)-1]
			e.vars = e.vars[:len(e.vars)-1]
			break
		}
	}
	e.vars = append(e.vars, key+"="+value)
}

func execEnvName(key string) string {
	return strings.ToUpper(strings.ReplaceAll(key, "-", "_"))
}

func (e *environ) load(ctx context.Context, store secretStore, service string) error {
	raw, err := store.ListRaw(ctx, service)
	if err != nil {
		return fmt.Errorf("Failed to list store contents: %w", err)
	}
	if e.strict {
		return e.loadStrict(raw)
	}
	for key, value := range raw {
		name := execEnvName(key)
		if e.has(name) {
			fmt.Fprintf(os.Stderr, "warning: service %s overwriting environment variable %s\n", service, name)
		}
		e.set(name, value)
	}
	return nil
}

func (e *environ) loadStrict(raw map[string]string) error {
	secrets := map[string]string{}
	for key, value := range raw {
		secrets[execEnvName(key)] = value
	}
	parent := append([]string(nil), e.vars...)
	for _, kv := range parent {
		key, value := splitEnvVar(kv)
		normalized := execEnvName(key)
		if value == e.strictValue {
			if key != normalized {
				return fmt.Errorf("parent env has key `%s` with expected value `%s`, but key is not normalized like `%s`, so would never get substituted", key, e.strictValue, normalized)
			}
			secretValue, ok := secrets[key]
			if !ok {
				return fmt.Errorf("parent env was expecting %s=%s, but was not in store", key, e.strictValue)
			}
			e.set(key, secretValue)
		} else if _, ok := secrets[key]; ok {
			return fmt.Errorf("parent env has %s, but was expecting value `%s`, not `%s`", key, e.strictValue, value)
		}
	}
	return nil
}

func (e *environ) Load(ctx context.Context, store secretStore, services []string) error {
	for _, service := range services {
		if err := e.load(ctx, store, service); err != nil {
			return err
		}
	}
	return nil
}

func (e *environ) Exec(args []string) error {
	slog.Debug(fmt.Sprintf("info: With environment %s\n", strings.Join(e.vars, ",")))
	path, err := exec.LookPath(args[0])
	if err != nil {
		return err
	}
	return syscall.Exec(path, args, e.vars)
}
