{"command":"cat > import_decode.go <<'GO'
package main

import (
	"bytes"
	"fmt"
	"io"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

func decodeImport(r io.Reader) (map[string]string, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	if len(bytes.TrimSpace(data)) == 0 {
		return nil, io.EOF
	}
	dec := yaml.NewDecoder(bytes.NewReader(data))
	var doc yaml.Node
	if err := dec.Decode(&doc); err != nil {
		return nil, err
	}
	if len(doc.Content) == 0 {
		return nil, io.EOF
	}
	root := derefAlias(doc.Content[0])
	if root.Kind == yaml.ScalarNode && root.Tag == "!!null" {
		return nil, io.EOF
	}
	if root.Kind != yaml.MappingNode {
		return nil, goccyError(data, root.Line, root.Column, fmt.Sprintf("%s was used where mapping is expected", yamlNodeTypeName(root)))
	}

	out := map[string]string{}
	seen := map[string]*yaml.Node{}
	if err := importMapping(data, root, out, seen); err != nil {
		return nil, err
	}
	return out, nil
}

func importMapping(data []byte, root *yaml.Node, out map[string]string, seen map[string]*yaml.Node) error {
	for i := 0; i+1 < len(root.Content); i += 2 {
		keyNode := derefAlias(root.Content[i])
		valNode := derefAlias(root.Content[i+1])

		if keyNode.Tag == "!!merge" && keyNode.Value == "<<" {
			// Basic YAML merge support.
			switch valNode.Kind {
			case yaml.MappingNode:
				if err := importMapping(data, valNode, out, seen); err != nil {
					return err
				}
			case yaml.SequenceNode:
				for _, item := range valNode.Content {
					item = derefAlias(item)
					if item.Kind == yaml.MappingNode {
						if err := importMapping(data, item, out, seen); err != nil {
							return err
						}
					}
				}
			}
			continue
		}

		key, err := importKey(data, keyNode)
		if err != nil {
			return err
		}
		if first, dup := seen[key]; dup {
			return goccyError(data, keyNode.Line, keyNode.Column, fmt.Sprintf("mapping key %q already defined at [%d:%d]", key, first.Line, first.Column))
		}
		value, err := importValue(data, valNode)
		if err != nil {
			return err
		}
		seen[key] = keyNode
		out[key] = value
	}
	return nil
}

func derefAlias(n *yaml.Node) *yaml.Node {
	for n != nil && n.Kind == yaml.AliasNode {
		n = n.Alias
	}
	return n
}

func yamlNodeTypeName(n *yaml.Node) string {
	switch n.Kind {
	case yaml.SequenceNode:
		return "sequence"
	case yaml.MappingNode:
		return "mapping"
	case yaml.ScalarNode:
		switch n.Tag {
		case "!!int":
			return "int"
		case "!!float":
			return "float"
		case "!!bool":
			return "bool"
		case "!!null":
			return "null"
		default:
			return "string"
		}
	}
	return "string"
}

func importKey(data []byte, n *yaml.Node) (string, error) {
	if n.Kind != yaml.ScalarNode {
		// goccy points after the key node for container keys.
		line, col := n.Line, n.Column
		if len(n.Content) > 0 {
			last := n.Content[len(n.Content)-1]
			line, col = last.Line, last.Column+len(last.Value)
