{"command":"cat > main.go <<'GO'
package main

import (
	"bufio"
	"fmt"
	"io"
	"log/slog"
	"os"
	"sort"
	"strings"
	"text/tabwriter"

	"github.com/spf13/cobra"
)

var (
	backendFlag         string
	backendS3BucketFlag string
	kmsKeyAliasFlag     string
	retriesFlag         int
	retryModeFlag       string
	verboseFlag         bool
)

const version = "dev"

func main() {
	if err := newRootCmd().Execute(); err != nil {
		os.Exit(1)
	}
}

func newRootCmd() *cobra.Command {
	root := &cobra.Command{
		Use:   "chamber",
		Short: "CLI for storing secrets",
		PersistentPreRun: func(cmd *cobra.Command, args []string) {
			if verboseFlag {
				slog.SetDefault(slog.New(slog.NewTextHandler(os.Stderr, &slog.HandlerOptions{Level: slog.LevelDebug})))
			}
		},
	}
	pf := root.PersistentFlags()
	pf.StringVarP(&backendFlag, "backend", "b", "ssm", "Backend to use; AKA $CHAMBER_SECRET_BACKEND\n\tnull: no-op\n\tssm: SSM Parameter Store\n\tsecretsmanager: Secrets Manager\n\ts3: S3; requires --backend-s3-bucket\n\ts3-kms: S3 using AWS-KMS encryption; requires --backend-s3-bucket and --kms-key-alias set (if you want to write or delete keys).")
	pf.StringVar(&backendS3BucketFlag, "backend-s3-bucket", "", "bucket for S3 backend; AKA $CHAMBER_S3_BUCKET")
	pf.StringVar(&kmsKeyAliasFlag, "kms-key-alias", defaultKMSKeyAlias, "KMS Key Alias for writing and deleting secrets; AKA $CHAMBER_KMS_KEY_ALIAS. This option is currently only supported for the S3-KMS backend.")
	pf.IntVarP(&retriesFlag, "retries", "r", 10, "For SSM or Secrets Manager, the number of retries we'll make before giving up; AKA $CHAMBER_RETRIES")
	pf.StringVar(&retryModeFlag, "retry-mode", "standard", "For SSM, the model used to retry requests\nstandard\nadaptive")
	pf.BoolVar(&verboseFlag, "verbose", false, "Print more information to STDERR")

	root.AddCommand(
		newDeleteCmd(),
		newEnvCmd(),
		newExecCmd(),
		newExportCmd(),
		newFindCmd(),
		newHistoryCmd(),
		newImportCmd(),
		newListCmd(),
		newListServicesCmd(),
		newReadCmd(),
		newTagCmd(),
		newVersionCmd(),
		newWriteCmd(),
	)
	return root
}

func storeForCmd(cmd *cobra.Command) (secretStore, error) {
	store, err := getSecretStore(cmd)
	if err != nil {
		return nil, fmt.Errorf("Failed to get secret store: %w", err)
	}
	return store, nil
}

func validateID(service, key string) error {
	if err := validateService(service, false); err != nil {
		return err
	}
	if err := validateKey(key); err != nil {
		return err
	}
	return nil
}

func secretID(service, key string, lowerKey bool) SecretID {
	if lowerKey {
		key = strings.ToLower(key)
	}
	return SecretID{Service: service, Key: key}
}

func newVersionCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "version",
		Short: "print version",
		Run: func(cmd *cobra.Command, args []string) {
			fmt.Printf("chamber %s\n", version)
		},
	}
}

func newWriteCmd() *cobra.Command {
	var singleline bool
	var skipUnchanged bool
	var tags map[string]string
	cmd := &cobra.Command{
		Use:   "write <service> <key> [--] <value|->",
		Short: "write a secret",
		Args:  cobra.ExactArgs(3),
		RunE: func(cmd *cobra.Command, args []string) error {
			service, key, value := args[0], args[1], args[2]
			if err := validateID(service, key); err != nil {
				return err
			}
			id := secretID(service, key, true)
			if value == "-" {
				if singleline {
					line, err := bufio.NewReader(os.Stdin).ReadString('\n')
					if err != nil {
						return err
					}
					value = strings.TrimSuffix(line, "\n")
				} else {
					data, err := io.ReadAll(os.Stdin)
					if err != nil {
						return err
					}
					value = string(data)
				}
			}
			store, err := storeForCmd(cmd)
			if err != nil {
				return err
			}
			ctx := cmd.Context()
			if skipUnchanged {
				if existing, err := store.Read(ctx, id, -1); err == nil && existing.Value == value {
					return nil
				}
			}
			if len(tags) > 0 {
				return store.WriteWithTags(ctx, id, value, tags)
			}
			return store.Write(ctx, id, value)
		},
	}
	cmd.Flags().BoolVarP(&singleline, "singleline", "s", false, `Insert single line parameter (end with \n)`)
	cmd.Flags().BoolVar(&skipUnchanged, "skip-unchanged", false, "Skip writing secret if value is unchanged")
	cmd.Flags().StringToStringVarP(&tags, "tags", "t", nil, "Add tags to the secret; new secrets only")
	return cmd
}

func newReadCmd() *cobra.Command {
	var quiet bool
	var readVersion int
	cmd := &cobra.Command{
		Use:   "read <service> <key>",
		Short: "Read a specific secret from the parameter store",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			if err := validateID(args[0], args[1]); err != nil {
				return err
			}
			store, err := storeForCmd(cmd)
			if err != nil {
				return err
			}
			secret, err := store.Read(cmd.Context(), secretID(args[0], args[1], true), int64(readVersion))
			if err != nil {
				return fmt.Errorf("Failed to read: %w", err)
			}
			if quiet {
				fmt.Println(secret.Value)
				return nil
			}
			w := newTabWriter()
			fmt.Fprintln(w, "Key\tValue\tVersion\tLastModified\tUser")
			fmt.Fprintf(w, "%s\t%s\t%d\t%s\t%s\n", secret.ID.Key, secret.Value, secret.Version, formatTime(secret.LastModified), secret.User)
			return w.Flush()
		},
	}
	cmd.Flags().BoolVarP(&quiet, "quiet", "q", false, "Only print the secret")
