func newListCmd() *cobra.Command {
	var expand, sortTime, sortUser, sortVersion bool
	cmd := &cobra.Command{
		Use:   "list <service>",
		Short: "List the secrets set for a service",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			if err := validateService(args[0], true); err != nil {
				return err
			}
			store, err := storeForCmd(cmd)
			if err != nil {
				return err
			}
			secrets, err := store.List(cmd.Context(), args[0], expand)
			if err != nil {
				return fmt.Errorf("Failed to list store contents: %w", err)
			}
			sort.Slice(secrets, func(i, j int) bool { return secrets[i].ID.Key < secrets[j].ID.Key })
			if sortTime {
				sort.SliceStable(secrets, func(i, j int) bool { return secrets[i].LastModified.Before(secrets[j].LastModified) })
			}
			if sortUser {
				sort.SliceStable(secrets, func(i, j int) bool { return secrets[i].User < secrets[j].User })
			}
			if sortVersion {
				sort.SliceStable(secrets, func(i, j int) bool { return secrets[i].Version < secrets[j].Version })
			}
			w := newTabWriter()
			header := "Key\tVersion\tLastModified\tUser"
			if expand {
				header += "\tValue"
			}
			fmt.Fprintln(w, header)
			for _, s := range secrets {
				line := fmt.Sprintf("%s\t%d\t%s\t%s", s.ID.Key, s.Version, formatTime(s.LastModified), s.User)
				if expand {
					line += "\t" + s.Value
				}
				fmt.Fprintln(w, line)
			}
			return w.Flush()
		},
	}
	cmd.Flags().BoolVarP(&expand, "expand", "e", false, "Expand parameter list with values")
	cmd.Flags().BoolVarP(&sortTime, "time", "t", false, "Sort by modified time")
	cmd.Flags().BoolVarP(&sortUser, "user", "u", false, "Sort by user")
	cmd.Flags().BoolVarP(&sortVersion, "version", "v", false, "Sort by version")
	return cmd
}

