		Short: "Find the given secret across all services",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			store, err := storeForCmd(cmd)
			if err != nil {
				return err
			}
			ctx := cmd.Context()
			if byValue {
				services, err := store.ListServices(ctx, "", false)
				if err != nil {
					return fmt.Errorf("Failed to list store contents: %w", err)
				}
				w := newTabWriter()
				fmt.Fprintln(w, "Service\tKey")
				for _, service := range services {
					secrets, err := store.List(ctx, service, true)
					if err != nil {
						continue
					}
					for _, s := range secrets {
						if s.Value == args[0] {
							fmt.Fprintf(w, "%s\t%s\n", service, s.ID.Key)
						}
					}
				}
				return w.Flush()
			}

			names, err := store.ListServices(ctx, "", true)
			if err != nil {
				return fmt.Errorf("Failed to list store contents: %w", err)
			}
			matches := map[string]bool{}
			for _, name := range names {
				trimmed := strings.TrimPrefix(name, "/")
				service, key := "", trimmed
				if i := strings.LastIndex(trimmed, "/"); i >= 0 {
					service, key = trimmed[:i], trimmed[i+1:]
				}
				if key == args[0] {
					matches[service] = true
				}
			}
			w := newTabWriter()
			fmt.Fprintln(w, "Service")
			for service := range matches {
				fmt.Fprintln(w, service)
			}
			return w.Flush()
		},
	}
	cmd.Flags().BoolVarP(&byValue, "by-value", "v", false, "Find parameters by value")
	return cmd
}

func newImportCmd() *cobra.Command {
	var normalizeKeys bool
	cmd := &cobra.Command{
		Use:   "import <service> <file|->",
		Short: "import secrets from json or yaml",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			service, source := args[0], args[1]
			if err := validateService(service, false); err != nil {
				return err
			}
			var reader io.Reader
			if source == "-" {
				reader = os.Stdin
			} else {
				file, err := os.Open(source)
				if err != nil {
					return fmt.Errorf("Failed to open file: %w", err)
				}
				defer file.Close()
				reader = file
			}
			secrets, err := decodeImport(reader)
			if err != nil {
				return fmt.Errorf("Failed to decode input as json: %w", err)
			}
			store, err := storeForCmd(cmd)
			if err != nil {
				return err
			}
			for key, value := range secrets {
				writeKey := key
				if normalizeKeys {
					writeKey = strings.ToLower(writeKey)
				}
				if err := store.Write(cmd.Context(), SecretID{Service: service, Key: writeKey}, value); err != nil {
					return fmt.Errorf("Failed to write secret: %w", err)
				}
			}
			fmt.Printf("Successfully imported %d secrets\n", len(secrets))
			return nil
		},
	}
	cmd.Flags().BoolVar(&normalizeKeys, "normalize-keys", false, "Normalize keys to match how `chamber write` would handle them. If not specified, keys will be written exactly how they are defined in the import source.")
	return cmd
}

func newExecCmd() *cobra.Command {
	var pristine, strict bool
	var strictValue string
	cmd := &cobra.Command{
		Use:   "exec <service...> -- <command> [<arg...>]",
		Short: "Executes a command with secrets loaded into the environment",
		Example: `
Given a secret store like this:

	$ echo '{"db_username": "root", "db_password": "hunter22"}' | chamber import - 

--strict will fail with unfilled env vars

	$ HOME=/tmp DB_USERNAME=chamberme DB_PASSWORD=chamberme EXTRA=chamberme chamber exec --strict service exec -- env
	chamber: extra unfilled env var EXTRA
	exit 1

--pristine takes effect after checking for --strict values

	$ HOME=/tmp DB_USERNAME=chamberme DB_PASSWORD=chamberme chamber exec --strict --pristine service exec -- env
	DB_USERNAME=root
	DB_PASSWORD=hunter22

`,
		Args: func(cmd *cobra.Command, args []string) error {
			dash := cmd.Flags().ArgsLenAtDash()
			if dash == -1 {
				return fmt.Errorf("please separate services and command with '--'. See usage")
			}
			if dash == 0 {
				return fmt.Errorf("at least one service must be specified: %w", cobra.MinimumNArgs(1)(cmd, args[:dash]))
			}
			if dash == len(args) {
				return fmt.Errorf("must specify command to run. See usage: %w", cobra.MinimumNArgs(1)(cmd, args[dash:]))
			}
			return nil
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			dash := cmd.Flags().ArgsLenAtDash()
			services := args[:dash]
			command := args[dash:]
			for _, service := range services {
				if err := validateService(service, true); err != nil {
					return err
				}
			}
			store, err := storeForCmd(cmd)
			if err != nil {
				return err
			}
			env := newEnviron(pristine, strict, strictValue)
			if err := env.Load(cmd.Context(), store, services); err != nil {
				return err
			}
			return env.Exec(command)
		},
	}
	cmd.Flags().BoolVar(&pristine, "pristine", false, "only use variables retrieved from the backend; do not inherit existing environment variables")
	cmd.Flags().BoolVar(&strict, "strict", false, "enable strict mode:\nonly inject secrets for which there is a corresponding env var with value\n<strict-value>, and fail if there are any env vars with that value missing\nfrom secrets")
	cmd.Flags().StringVar(&strictValue, "strict-value", "chamberme", "value to expect in --strict mode")
	return cmd
}

