					value = strings.TrimSuffix(line, "\n")
				} else {
					data, err := io.ReadAll(os.Stdin)
					if err != nil {
						return err
					}
					value = string(data)
				}
			}
			store, err := storeForCmd(cmd)
			if err != nil {
				return err
			}
			ctx := cmd.Context()
			if skipUnchanged {
				if existing, err := store.Read(ctx, id, -1); err == nil && existing.Value == value {
					return nil
				}
			}
			if len(tags) > 0 {
				return store.WriteWithTags(ctx, id, value, tags)
			}
			return store.Write(ctx, id, value)
		},
	}
	cmd.Flags().BoolVarP(&singleline, "singleline", "s", false, `Insert single line parameter (end with \n)`)
	cmd.Flags().BoolVar(&skipUnchanged, "skip-unchanged", false, "Skip writing secret if value is unchanged")
	cmd.Flags().StringToStringVarP(&tags, "tags", "t", nil, "Add tags to the secret; new secrets only")
	return cmd
}

