func newTagWriteCmd() *cobra.Command {
	var deleteOther bool
	cmd := &cobra.Command{
		Use:   "write <service> <key> <tag>...",
		Short: "Write tags for a specific secret",
		Args:  cobra.MinimumNArgs(3),
		RunE: func(cmd *cobra.Command, args []string) error {
			if err := validateID(args[0], args[1]); err != nil {
				return err
			}
			tags := map[string]string{}
			for _, raw := range args[2:] {
				parts := strings.SplitN(raw, "=", 2)
				if len(parts) != 2 {
					return fmt.Errorf("Failed to parse tag %s: tag must be in the form key=value", raw)
				}
				k, v := parts[0], parts[1]
				if err := validateTagKeyName(k); err != nil {
					return fmt.Errorf("Failed to validate tag with key %s: %w", k, err)
				}
				if err := validateTagValueName(v); err != nil {
					return fmt.Errorf("Failed to validate tag with key %s: %w", k, err)
				}
				tags[k] = v
			}
			store, err := storeForCmd(cmd)
			if err != nil {
				return err
			}
			if err := store.WriteTags(cmd.Context(), secretID(args[0], args[1], true), tags, deleteOther); err != nil {
				return fmt.Errorf("Failed to write tags: %w", err)
			}
			return printTagMap(tags)
		},
	}
	cmd.Flags().BoolVar(&deleteOther, "delete-other-tags", false, "Delete tags not specified in the command")
	return cmd
}

func newTagDeleteCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "delete <service> <key> <tag key>...",
		Short: "Delete tags for a specific secret",
		Args:  cobra.MinimumNArgs(3),
		RunE: func(cmd *cobra.Command, args []string) error {
			if err := validateID(args[0], args[1]); err != nil {
				return err
			}
			for _, k := range args[2:] {
				if err := validateTagKeyName(k); err != nil {
					return fmt.Errorf("Failed to validate tag key %s: %w", k, err)
				}
			}
			store, err := storeForCmd(cmd)
			if err != nil {
				return err
			}
			if err := store.DeleteTags(cmd.Context(), secretID(args[0], args[1], true), args[2:]); err != nil {
				return fmt.Errorf("Failed to delete tags: %w", err)
			}
			return nil
		},
	}
}
