{"command":"cat > yaml_export.go <<'GO'
package main

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

func marshalYAMLStringMap(params map[string]string) string {
	if len(params) == 0 {
		return "{}\n"
	}
	var b strings.Builder
	for _, k := range sortedKeys(params) {
		b.WriteString(renderYAMLScalar(k))
		b.WriteString(": ")
		rendered := renderYAMLScalar(params[k])
		b.WriteString(rendered)
		if !strings.HasSuffix(rendered, "\n") {
			b.WriteString("\n")
		}
	}
	return b.String()
}

func renderYAMLScalar(s string) string {
	if s == "" {
		return `""`
	}
	if strings.ContainsAny(s, "\n\r") {
		if canUseYAMLLiteral(s) {
			return renderYAMLLiteral(s)
		}
		return doubleQuoteYAML(s)
	}
	if yamlPlainAllowed(s) {
		return s
	}
	return doubleQuoteYAML(s)
}

func yamlPlainAllowed(s string) bool {
	if s == "" {
		return false
	}
	if s[0] == ' ' || s[len(s)-1] == ' ' {
		return false
	}
	if strings.ContainsAny(s, "#\\") {
		return false
	}
	if strings.Contains(s, ": ") || strings.Contains(s, ":\t") || strings.HasSuffix(s, ":") {
		return false
	}
	if strings.Contains(s, "- ") || s == "-" {
		return false
	}
	if strings.ContainsRune("!\"#%&'*,>@[\\]`{|}", rune(s[0])) {
		return false
	}
	if looksLikeYAMLNonString(s) {
		return false
	}
	return true
}

var (
	yamlIntRe   = regexp.MustCompile(`^[-+]?([0-9][0-9_]*|0x[0-9a-fA-F_]+|0b[0-1_]+|0o[0-7_]+)$`)
	yamlFloatRe = regexp.MustCompile(`^[-+]?([0-9][0-9_]*\.[0-9_]*|\.[0-9]+)([eE][-+]?[0-9]+)?$`)
	yamlTimeRe  = regexp.MustCompile(`^[0-9]{1,2}:[0-5][0-9]$`)
	yamlDateRe  = regexp.MustCompile(`^[0-9]{4}-[0-9]{2}-[0-9]{2}$`)
)

func looksLikeYAMLNonString(s string) bool {
	switch s {
	case "~", "null", "Null", "NULL",
		"y", "Y", "yes", "Yes", "YES",
		"n", "N", "no", "No", "NO",
		"true", "True", "TRUE", "false", "False", "FALSE",
		"on", "On", "ON", "off", "Off", "OFF",
		".inf", ".Inf", "+.inf", "+.Inf", "-.inf", "-.Inf",
		".nan", ".Nan", ".NAN":
		return true
	}
	if yamlIntRe.MatchString(s) || yamlFloatRe.MatchString(s) || yamlTimeRe.MatchString(s) || yamlDateRe.MatchString(s) {
		return true
	}
	if _, err := time.Parse(time.RFC3339Nano, s); err == nil {
		return true
	}
	return false
}

func canUseYAMLLiteral(s string) bool {
	if s == "" {
		return false
	}
	if s[0] == ' ' || strings.HasSuffix(s, " ") {
		return false
	}
	if strings.ContainsAny(s, "#\\") {
		return false
	}
	if strings.Contains(s, ": ") || strings.Contains(s, ":\t") {
		return false
	}
	if strings.Contains(s, "- ") {
		return false
	}
	// A colon at the end of any line would also require quoting in the
	// reference emitter.
	for _, line := range strings.FieldsFunc(s, func(r rune) bool { return r == '\n' || r == '\r' }) {
		if strings.HasSuffix(line, ":") {
			return false
		}
	}
	if s[0] != '\n' && s[0] != '\r' && strings.ContainsRune("!\"#%&'*,>@[\\]`{|}", rune(s[0])) {
		return false
	}
	return true
}

type yamlLine struct {
	content string
	breakSeq string
}

func splitYAMLLines(s string) []yamlLine {
	var lines []yamlLine
	start := 0
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\n':
			lines = append(lines, yamlLine{s[start:i], "\n"})
			start = i + 1
		case '\r':
			if i+1 < len(s) && s[i+1] == '\n' {
				lines = append(lines, yamlLine{s[start:i], "\r\n"})
				i++
			} else {
				lines = append(lines, yamlLine{s[start:i], "\r"})
			}
			start = i + 1
		}
	}
	if start < len(s) {
		lines = append(lines, yamlLine{s[start:], ""})
	} else if start == len(s) && len(lines) == 0 {
		lines = append(lines, yamlLine{"", ""})
	}
	return lines
}

func renderYAMLLiteral(s string) string {
	lines := splitYAMLLines(s)
	// Count complete line breaks at the end.
	trailingBreaks := 0
	hasFinalBreak := len(lines) > 0 && lines[len(lines)-1].breakSeq != ""
	if hasFinalBreak {
		// Number of consecutive empty completed lines is not itself the
		// number of breaks; count completed lines from the end whose
		// content is empty, plus the break ending the last content line.
		trailingBreaks = 1
		for i := len(lines) - 2; i >= 0; i-- {
			if lines[i].content == "" && lines[i].breakSeq != "" {
				trailingBreaks++
			} else {
				break
			}
		}
		if len(lines) > 0 && lines[len(lines)-1].content == "" {
			// A single trailing newline normally advances the last
			// non-empty line by one break; additional empty lines add.
			// trailingBreaks already accounts for them above when all
			// lines are empty or empty lines precede the end. For the
			// common "a\n\n" shape, lines are [a\n, \n] and the loop
			// counted the final empty line as trailingBreaks=1; correct
			// it to 2.
			if len(lines) >= 2 {
				trailingBreaks = 1
				for i := len(lines) - 1; i >= 0 && lines[i].content == ""; i-- {
					trailingBreaks++
				}
			}
		}
	}
	indicator := "|-"
	if trailingBreaks == 1 {
		indicator = "|"
	} else if trailingBreaks > 1 {
		indicator = "|+"
	}

	lastNonEmpty := -1
	for i, l := range lines {
		if l.content != "" {
			lastNonEmpty = i
		}
	}
	var b strings.Builder
	b.WriteString(indicator)
	b.WriteString("\n")
	for i, l := range lines {
		if i <= lastNonEmpty {
			b.WriteString("  ")
			b.WriteString(l.content)
			if l.breakSeq != "" {
				b.WriteString(l.breakSeq)
			} else {
				b.WriteString("\n")
			}
			continue
		}
		if lastNonEmpty == -1 && i == 0 {
			// All lines empty: indent the first one.
			b.WriteString("  ")
			if l.breakSeq != "" {
				b.WriteString(l.breakSeq)
			} else {
				b.WriteString("\n")
			}
			continue
		}
		// Additional trailing blank lines are bare newlines.
		if l.breakSeq != "" {
			b.WriteString("\n")
		}
	}
	return b.String()
}

func doubleQuoteYAML(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	if !utf8.ValidString(s) {
		for i := 0; i < len(s); i++ {
			c := s[i]
			switch c {
			case '"':
				b.WriteString(`\"`)
			case '\\':
				b.WriteString(`\\`)
			case '\a':
				b.WriteString(`\a`)
			case '\b':
				b.WriteString(`\b`)
			case '\t':
				b.WriteString(`\t`)
			case '\n':
				b.WriteString(`\n`)
			case '\v':
				b.WriteString(`\v`)
			case '\f':
				b.WriteString(`\f`)
			case '\r':
				b.WriteString(`\r`)
			default:
				if c < 0x20 || c == 0x7f {
					fmt.Fprintf(&b, `\x%02x`, c)
				} else {
					b.WriteByte(c)
				}
			}
		}
		b.WriteByte('"')
		return b.String()
	}
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\a':
			b.WriteString(`\a`)
		case '\b':
			b.WriteString(`\b`)
		case '\t':
			b.WriteString(`\t`)
		case '\n':
			b.WriteString(`\n`)
		case '\v':
			b.WriteString(`\v`)
		case '\f':
			b.WriteString(`\f`)
		case '\r':
			b.WriteString(`\r`)
		case 0x1b:
			b.WriteString(`\e`)
		case 0x85:
			b.WriteString(`\N`)
		case 0xa0:
			b.WriteString(`\_`)
		case 0x2028:
			b.WriteString(`\L`)
		case 0x2029:
			b.WriteString(`\P`)
		default:
			if !strconv.IsPrint(r) {
				switch {
				case r < 0x100:
					fmt.Fprintf(&b, `\x%02x`, r)
				case r < 0x10000:
					fmt.Fprintf(&b, `\u%04x`, r)
				default:
					fmt.Fprintf(&b, `\U%08x`, r)
				}
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}
